#!/usr/bin/env bash
# Generated by scripts/build-revdoku-cli.rb; edit src/revdoku.sh.in.
set -euo pipefail
umask 077

DEFAULT_URL="https://api.revdoku.com"
APP_URL="https://app.revdoku.com"
MCP_RESOURCE="https://mcp.revdoku.com"
CREDENTIALS_PATH="${REVDOKU_CREDENTIALS:-${HOME}/.revdoku/credentials}"
DEFAULT_MAILBOX_PATH="${REVDOKU_DEFAULT_BUCKET_FILE:-${CREDENTIALS_PATH}.bucket}"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
DEVICE_CODE_GRANT_TYPE="urn:ietf:params:oauth:grant-type:device_code"

# Config dir + installed client version stamp (written by install.sh). Used for
# `--version` and the non-blocking update notice.
REVDOKU_CONFIG_DIR="$(dirname "$CREDENTIALS_PATH")"
CLIENT_VERSION_FILE="${REVDOKU_CLIENT_VERSION_FILE:-${REVDOKU_CONFIG_DIR}/client_version}"
UPDATE_CHECK_STAMP="${REVDOKU_CONFIG_DIR}/.update_check"

installed_client_version() {
  local v="unknown"
  if [[ -f "$CLIENT_VERSION_FILE" ]]; then
    v="$(tr -d '[:space:]' < "$CLIENT_VERSION_FILE" 2>/dev/null || true)"
    [[ -n "$v" ]] || v="unknown"
  fi
  printf '%s' "$v"
}

BASE_URL="${REVDOKU_URL:-$DEFAULT_URL}"
API_KEY="${REVDOKU_API_KEY:-}"
DESCRIPTION="${REVDOKU_BUCKET_DESCRIPTION:-}"
UPLOAD_MODE="${REVDOKU_UPLOAD_MODE:-auto}"
MAILBOX_ID="${REVDOKU_MAILBOX_ID:-}"
METADATA_JSON="${REVDOKU_BUCKET_METADATA:-}"
RESTORE_VERSION_ID="${REVDOKU_RESTORE_VERSION_ID:-}"
ACTION_REASON=""
BROWSER_LOGIN_PATH="${REVDOKU_BROWSER_LOGIN_PATH:-/mailboxes}"
APPEND_TEXT_PATH="${REVDOKU_APPEND_TEXT_PATH:-}"
APPEND_TEXT_CONTENT="${REVDOKU_APPEND_TEXT_CONTENT:-}"
APPEND_TEXT_CONTENT_FILE="${REVDOKU_APPEND_TEXT_CONTENT_FILE:-}"
APPEND_TEXT_NEWLINE_BEFORE="${REVDOKU_APPEND_TEXT_NEWLINE_BEFORE:-true}"
GRANT_TOKEN=""
ACCOUNT_ID=""
CLIENT_ACCOUNT_NAME=""
CLIENT_DISPLAY_NAME=""
AGENT_NAME="${REVDOKU_AGENT_NAME:-}"
AGENT_CLIENT="${REVDOKU_AGENT_CLIENT:-revdoku}"
AGENT_VERSION="${REVDOKU_AGENT_VERSION:-}"
if [[ -z "$AGENT_VERSION" ]]; then
  AGENT_VERSION="$(installed_client_version)"
  [[ "$AGENT_VERSION" == "unknown" ]] && AGENT_VERSION="0.1.0"
fi
AGENT_RUN_ID="${REVDOKU_AGENT_RUN_ID:-}"
AGENT_PROJECT="${REVDOKU_AGENT_PROJECT:-}"
AGENT_TASK="${REVDOKU_AGENT_TASK:-}"
MAILBOX_UPLOAD_DESCRIPTOR_BATCH_SIZE="${REVDOKU_BUCKET_UPLOAD_DESCRIPTOR_BATCH_SIZE:-25}"
MAILBOX_UPLOAD_CLIENT_SESSION_KEY="${REVDOKU_BUCKET_UPLOAD_CLIENT_SESSION_KEY:-}"
HTTP_TRANSIENT_MAX_ATTEMPTS="${REVDOKU_HTTP_TRANSIENT_MAX_ATTEMPTS:-5}"
HTTP_RETRYABLE_CONFLICT_MAX_ATTEMPTS="${REVDOKU_HTTP_RETRYABLE_CONFLICT_MAX_ATTEMPTS:-12}"
HTTP_LOCK_MAX_ATTEMPTS="${REVDOKU_HTTP_LOCK_MAX_ATTEMPTS:-3}"
DIRECT_UPLOAD_MAX_ATTEMPTS="${REVDOKU_DIRECT_UPLOAD_MAX_ATTEMPTS:-5}"
LOGIN="false"
ACTION="store"
PATH_TO_STORE=""
PATH_EXPLICIT="false"
MAILBOX_EXPLICIT="false"
DRY_RUN="false"
DELETE_CONFIRMATION=""
WEBHOOK_URL=""
ROTATE_SECRET="false"
UPLOAD_MANIFEST=""
UPLOAD_LOCAL_MAP=""
SKIPPED_PATHS=""
READ_FILE_PATH=""
EMAIL_ID=""
EMAIL_USERNAME=""
EMAIL_DOMAIN=""
MAILBOX_TITLE=""
EMAIL_ATTACHMENT_ID=""
LIST_LIMIT=""
LIST_CURSOR=""
VERSION_ID=""
EMAIL_SENDER=""
EMAIL_SUBJECT=""
EMAIL_CONVERSATION=""
EMAIL_READ=""
EMAIL_DIRECTION=""
# Newline-separated lists; Bash 3 rejects empty arrays under set -u.
EMAIL_TO=""
EMAIL_CC=""
EMAIL_ATTACHMENTS=""
EMAIL_TEXT=""
EMAIL_TEXT_FILE=""
EMAIL_HTML_FILE=""
EMAIL_IN_REPLY_TO=""
MAILBOX_LIST_STATUS="active"
MAILBOX_LIST_QUERY=""
MAILBOX_LIST_OPTIONS="false"
OUTPUT_PATH=""
SHOW_UPLOAD_HINT="false"
# Project-local binding (.revdoku): remembers the mailbox so `revdoku upload`
# updates the same stored files. Populated from the target dir, --mailbox-id overrides.
REVDOKU_PROJECT_FILE=""
BOUND_MAILBOX_ID=""
BINDING_EXISTED="false"
LAST_HTTP_STATUS=""
LAST_ERROR_CODE=""
LAST_ERROR_MESSAGE=""
LAST_ERROR_DETAILS_JSON=""

die() {
  echo "error: $1" >&2
  exit 1
}

need_cmd() {
  command -v "$1" >/dev/null 2>&1 || die "requires $1"
}

validate_base_url() {
  # Existing configurations using the app origin now use the dedicated API.
  [[ "$BASE_URL" != "$APP_URL" ]] || BASE_URL="$DEFAULT_URL"
  [[ "$BASE_URL" == "$DEFAULT_URL" ]] && return 0
  die "API/auth requests require https://api.revdoku.com"
}

safe_curl() {
  # -q must be the first argument: do not load implicit curl configuration.
  command curl -q --proto '=https' --proto-redir '=https' --globoff "$@"
}

validate_api_url() {
  [[ ( "$1" == "$BASE_URL/"* || "$1" == "$APP_URL/"* ) && "$1" != *[[:space:][:cntrl:]\\]* && "$1" != *'#'* ]] || die "untrusted API/auth URL"
}

validate_transfer_url() {
  local url="$1" rest origin
  [[ "$url" != *[[:space:][:cntrl:]\\]* && "$url" != *'#'* ]] || return 1
  [[ "$url" == "$BASE_URL/"* || "$url" == "$APP_URL/"* ]] && return 0
  [[ "$url" == https://*/* ]] || return 1
  rest="${url#https://}"
  origin="https://${rest%%/*}"
  "$JQ_BIN" -en --arg origin "$origin" '["https://revdoku-files-prod-eu-central-1.s3.eu-central-1.amazonaws.com"] | index($origin) != null' >/dev/null
}

validate_id() {
  [[ "$2" =~ ^[A-Za-z0-9_-]+$ ]] || die "invalid $1"
}

no_symlink_components() {
  local path="$1"
  while [[ "$path" != / && "$path" != . && -n "$path" ]]; do
    [[ ! -L "$path" ]] || return 1
    path="$(dirname "$path")"
  done
}

# Resolve a caller-selected parent once (including system aliases such as /var),
# keeping the final filename separate so a destination symlink is never followed.
local_file_path() {
  local parent name
  parent="$(dirname -- "$1")"
  name="$(basename -- "$1")"
  parent="$(cd -P -- "$parent" && pwd -P)" || return 1
  printf '%s/%s' "${parent%/}" "$name"
}

atomic_private_write() {
  local path="$1" parent tmp
  [[ ! -L "$path" ]] || die "refusing to write through a symlink"
  [[ ! -e "$path" || -f "$path" ]] || die "destination must be a regular file"
  parent="$(dirname "$path")"
  mkdir -p -- "$parent" || return 1
  path="$(local_file_path "$path")" || return 1
  parent="$(dirname "$path")"
  [[ ! -L "$path" ]] || die "refusing to write through a symlink"
  tmp="$(mktemp "$parent/.revdoku-write.XXXXXX")" || return 1
  if ! cat > "$tmp" || ! chmod 0600 "$tmp" || [[ -L "$path" || ( -e "$path" && ! -f "$path" ) ]] || ! mv -f "$tmp" "$path"; then
    rm -f "$tmp"
    return 1
  fi
}

# Identify the AI agent or tool driving this CLI so uploads are attributed to
# the real caller (claude-code, codex, ...) instead of a generic "cli".
# Precedence: --agent flag / REVDOKU_AGENT_NAME override this entirely; this
# function only runs as the fallback. Always degrades safely to "cli".
detect_agent_name() {
  if [[ -n "${CLAUDECODE:-}" || -n "${CLAUDE_CODE_ENTRYPOINT:-}" ]]; then
    printf 'claude-code'
  elif [[ -n "${CODEX_SANDBOX:-}" || -n "${CODEX_HOME:-}" ]]; then
    printf 'codex'
  elif [[ -n "${CURSOR_TRACE_ID:-}" ]]; then
    printf 'cursor'
  elif [[ -n "${AI_AGENT:-}" ]]; then
    # Generic convention, e.g. AI_AGENT="claude-code_2-1-173_agent" -> "claude-code"
    printf '%s' "${AI_AGENT%%_*}"
  else
    printf 'cli'
  fi
}

usage() {
  cat <<USAGE
revdoku: mailboxes for AI agents, with private file storage.

Usage: revdoku <command> [PATH] [options]

  upload PATH           Save the selected local file or folder (use . explicitly).
                        Opens browser sign-in when credentials are missing.
  ls, list              List active mailboxes with titles, addresses and email counts.
  create                Create a mailbox; optionally choose --username, --domain and --title.
  o, open               Open this mailbox in the dashboard.
  st, status            Show connection and account status.
  login                 Sign in to an existing account in the browser.
  grant TOKEN           Use a one-time connection token from the web app.
  mailbox                 Show incoming address, readiness, and email activity.
  emails                List received emails; returns a resumable polling cursor.
  email ID              Read decoded email without changing shared read status.
  email-status ID       Set shared read status with --read true|false.
  email-download ID     Download original EML or --attachment-id ID.
  email-delete ID       Delete an email and attachments; confirm with --confirm-delete ID.
  email-send            Send from this mailbox to allowed recipients. Does not retry.
  webhook               Show the mailbox webhook endpoint.
  webhook-set           Set --webhook-url HTTPS_URL; optionally --rotate-secret.
  webhook-delete        Disable the webhook; requires --confirm-delete MAILBOX_ID.
  email-subscription    Get a short-lived WebSocket ticket for a running client.
  files                 List mailbox files.
  read PATH             Read a mailbox file; --output FILE saves it locally.
  versions PATH         List one file's versions (PATH or a df_ file ID).
  restore PATH          Restore one file version; requires --version-id ID.
  append PATH           Append text; --content TEXT or --content-file FILE.
  archive | unarchive    Manage a mailbox.
  delete                Preview permanent deletion; requires explicit account/mailbox.
  accounts              List accounts granted to this credential.
  account limits                 Read effective mailbox and storage quotas
  account get ID        Read one granted account.
  account               Account identity and effective limits.
  account create-client NAME     Create a client account within an authorized agency.
  dashboard             Print the dashboard URL; normal sign-in is required.

Options:
  --reason TEXT         Optional purpose for this action (up to 2000 characters).
                        AI agents should explain intentional reads and changes.
  --account-id ID       Select a granted account for this command.
  --client-name NAME    Client person or business (account create-client).
  --mailbox-id ID        Target mailbox; overrides the local .revdoku binding.
  --status active|archived|all          Mailbox list filter (default: active).
  --query TEXT                        Mailbox title, address or ID filter (ls).
  --limit N   --cursor CURSOR          List page size (maximum 200) and next page.
                                       Use pagination.next_cursor from the last page.
  --sender ADDRESS     --subject TEXT  Email filters.
  --direction received|sent|all        Email direction filter (default received).
  --conversation-id ID                 Filter an email conversation.
  --in-reply-to EMAIL_ID               email-send: reply to a received email.
                                       Sets the default recipient and subject.
  --to ADDRESS   --cc ADDRESS          email-send recipients; repeat (10 maximum).
                                       Recipients must be addresses that emailed this
                                       mailbox and passed sender authentication.
  --subject TEXT                       email-send subject (optional for replies).
  --text TEXT | --text-file PATH       email-send plain-text body (- reads stdin).
  --html-file PATH     --attach FILE_ID   Optional HTML body; attach mailbox files.
  --read true|false                    Email filter or desired read status.
  --attachment-id ID   --output FILE   Download a selected email attachment.
  --version-id ID                      File version for read or restore.
  --description TEXT   --metadata JSON
  --username NAME      --domain HOST          Mailbox creation address options.
  --title TEXT                                Mailbox title for create (default: the username).
  --dry-run            Preview an upload locally, without network requests.
  --confirm-delete TOKEN  Execute a reviewed deletion preview (expires in 10 minutes).
  --api-key KEY        API credential (or REVDOKU_API_KEY / $CREDENTIALS_PATH).
  --agent NAME         Attribute uploads (default: auto-detected).
  --upload-mode MODE   auto or direct (default: auto).
  --version            Print installed client version.
  -h, --help           Show this help.

Examples:
  revdoku upload ./project-files
  revdoku files --mailbox-id bkt_...
  revdoku read notes.md --mailbox-id bkt_... --reason "Review project decisions"
  revdoku dashboard

Plans: https://app.revdoku.com/pricing
USAGE
}

# ---------------------------------------------------------------------------
# Command parsing. The first non-option token is the verb (upload, ls, open …);
# options may appear before or after it. A bare path (`revdoku .`) stores files;
# no args at all shows status + a hint. The most common verb is the shortest.
# ---------------------------------------------------------------------------
VERB_SEEN="false"
ORIGINAL_ARGC=$#

while [[ $# -gt 0 ]]; do
  case "$1" in
    --api-key)
      [[ $# -ge 2 ]] || die "--api-key requires a value"
      API_KEY="$2"
      shift 2
      ;;
    --webhook-url)
      [[ $# -ge 2 ]] || die "--webhook-url requires a value"
      WEBHOOK_URL="$2"; shift 2 ;;
    --rotate-secret) ROTATE_SECRET="true"; shift ;;
    --url)
      [[ $# -ge 2 ]] || die "--url requires a value"
      BASE_URL="$2"
      shift 2
      ;;
    --username|--domain)
      [[ $# -ge 2 && -n "$2" && "$2" != -* ]] || die "$1 requires a value"
      case "$1" in
        --username) EMAIL_USERNAME="$2" ;;
        --domain) EMAIL_DOMAIN="$2" ;;
      esac
      shift 2
      ;;
    --description)
      [[ $# -ge 2 ]] || die "--description requires a value"
      DESCRIPTION="$2"
      shift 2
      ;;
    --title)
      [[ $# -ge 2 && -n "$2" ]] || die "--title requires a value"
      MAILBOX_TITLE="$2"
      shift 2
      ;;
    --account-id)
      [[ $# -ge 2 && -n "$2" && "$2" != -* ]] || die "--account-id requires an account id"
      ACCOUNT_ID="$2"
      shift 2
      ;;
    --client-name)
      [[ $# -ge 2 && -n "$2" && "$2" != -* ]] || die "--client-name requires a client name"
      CLIENT_DISPLAY_NAME="$2"
      shift 2
      ;;
    --mailbox-id)
      [[ $# -ge 2 ]] || die "--mailbox-id requires a value"
      MAILBOX_ID="$2"
      MAILBOX_EXPLICIT="true"
      shift 2
      ;;
    --status|--query)
      [[ $# -ge 2 && -n "$2" ]] || die "$1 requires a value"
      if [[ "$1" == "--status" ]]; then
        case "$2" in active|archived|all) MAILBOX_LIST_STATUS="$2" ;; *) die "--status must be active, archived or all" ;; esac
      else
        MAILBOX_LIST_QUERY="$2"
      fi
      MAILBOX_LIST_OPTIONS="true"
      shift 2
      ;;
    --cursor|--limit|--sender|--subject|--conversation-id|--read|--attachment-id|--version-id)
      [[ $# -ge 2 && -n "$2" ]] || die "$1 requires a value"
      case "$1" in
        --cursor) LIST_CURSOR="$2" ;;
        --limit) [[ "$2" =~ ^[1-9][0-9]*$ && "$2" -le 200 ]] || die "--limit must be from 1 to 200"; LIST_LIMIT="$2" ;;
        --version-id) VERSION_ID="$2" ;;
        --sender) EMAIL_SENDER="$2" ;;
        --subject) EMAIL_SUBJECT="$2" ;;
        --conversation-id) EMAIL_CONVERSATION="$2" ;;
        --read) [[ "$2" == "true" || "$2" == "false" ]] || die "--read must be true or false"; EMAIL_READ="$2" ;;
        --attachment-id) EMAIL_ATTACHMENT_ID="$2" ;;
      esac
      shift 2
      ;;
    --to|--cc|--attach|--in-reply-to|--direction|--text|--text-file|--html-file)
      [[ $# -ge 2 && -n "$2" ]] || die "$1 requires a value"
      case "$1" in
        --to|--cc|--attach|--in-reply-to|--direction)
          [[ "$2" != *$'\n'* ]] || die "$1 requires a single value" ;;
      esac
      case "$1" in
        --to) EMAIL_TO+="$2"$'\n' ;;
        --cc) EMAIL_CC+="$2"$'\n' ;;
        --attach) [[ "$2" =~ ^df_[A-Za-z0-9]+$ ]] || die "--attach requires a mailbox file id"; EMAIL_ATTACHMENTS+="$2"$'\n' ;;
        --in-reply-to) [[ "$2" =~ ^eml_[A-Za-z0-9]+$ ]] || die "--in-reply-to requires an email id"; EMAIL_IN_REPLY_TO="$2" ;;
        --direction) [[ "$2" =~ ^(received|sent|all)$ ]] || die "--direction must be received, sent or all"; EMAIL_DIRECTION="$2" ;;
        --text) EMAIL_TEXT="$2" ;;
        --text-file) EMAIL_TEXT_FILE="$2" ;;
        --html-file) EMAIL_HTML_FILE="$2" ;;
      esac
      shift 2
      ;;
    --metadata)
      [[ $# -ge 2 ]] || die "--metadata requires a JSON object"
      METADATA_JSON="$2"
      shift 2
      ;;
    --agent)
      [[ $# -ge 2 ]] || die "--agent requires a value"
      AGENT_NAME="$2"
      shift 2
      ;;
    --output)
      [[ $# -ge 2 ]] || die "--output requires a value"
      OUTPUT_PATH="$2"
      shift 2
      ;;
    --reason)
      [[ $# -ge 2 ]] || die "--reason requires a value"
      ACTION_REASON="$2"
      shift 2
      ;;
    --content)
      [[ $# -ge 2 ]] || die "--content requires a value"
      APPEND_TEXT_CONTENT="$2"
      shift 2
      ;;
    --content-file)
      [[ $# -ge 2 ]] || die "--content-file requires a local file path or -"
      APPEND_TEXT_CONTENT_FILE="$2"
      shift 2
      ;;
    --no-newline-before)
      APPEND_TEXT_NEWLINE_BEFORE="false"
      shift
      ;;
    --upload-mode)
      [[ $# -ge 2 ]] || die "--upload-mode requires a value"
      UPLOAD_MODE="$2"
      shift 2
      ;;
    --dry-run)
      DRY_RUN="true"
      shift
      ;;
    --confirm-delete)
      [[ $# -ge 2 && -n "$2" ]] || die "--confirm-delete requires a preview token"
      DELETE_CONFIRMATION="$2"
      shift 2
      ;;
    --version)
      printf '%s\n' "$(installed_client_version)"
      printf 'Latest: https://github.com/revdoku/revdoku — update using your original installation method: https://revdoku.com/llms-install.md\n' >&2
      exit 0
      ;;
    --login)
      # Compatibility with older public prompts. `revdoku login` is the
      # canonical spelling, but existing copied instructions must keep working.
      LOGIN="true"
      shift
      ;;
    -h|--help)
      usage
      exit 0
      ;;
    --)
      shift
      break
      ;;
    -*)
      die "unknown option: $1 (run 'revdoku --help')"
      ;;
    *)
      if [[ "$VERB_SEEN" == "true" ]]; then
        [[ "$PATH_EXPLICIT" == "false" && "$ACTION" == "store" ]] || die "unexpected positional argument"
        PATH_TO_STORE="$1"
        PATH_EXPLICIT="true"
        shift
      else
        VERB_SEEN="true"
        case "$1" in
          upload|put)     shift ;;
          p|publish|down|unpublish|preview|sites|analytics|i|init)
            die "This command is unavailable. Use revdoku --help for storage commands." ;;
          ls|list)        ACTION="list_mailboxes"; shift ;;
          accounts)       ACTION="list_accounts"; shift ;;
          create)         ACTION="create_mailbox"; shift ;;
          o|open)         ACTION="open_dashboard"; shift ;;
          st|status)      ACTION="connection_status"; shift ;;
          login)          LOGIN="true"; shift ;;
          grant)          [[ $# -ge 2 && "$2" != -* ]] || die "grant needs the one-time token right after it"; ACTION="exchange_grant"; GRANT_TOKEN="$2"; shift 2 ;;
          webhook|webhook-set|webhook-delete|email-subscription) ACTION="$1"; shift ;;
          emails)         ACTION="list_emails"; shift ;;
          email-send)     ACTION="email-send"; shift ;;
          email|email-status|email-download|email-delete)
            [[ $# -ge 2 && "$2" != -* ]] || die "$1 requires an email id"
            ACTION="$1"; EMAIL_ID="$2"; shift 2 ;;
          files)          ACTION="list_files"; shift ;;
          mailbox)          ACTION="mailbox_status"; shift ;;
          read)           [[ $# -ge 2 && "$2" != -* ]] || die "read needs a mailbox PATH right after it, e.g. revdoku read notes.md --mailbox-id ID"; ACTION="read_file"; READ_FILE_PATH="$2"; shift 2 ;;
          versions)       [[ $# -ge 2 && "$2" != -* ]] || die "versions needs a mailbox PATH right after it, e.g. revdoku versions notes.md --mailbox-id ID"; ACTION="list_versions"; READ_FILE_PATH="$2"; shift 2 ;;
          restore)        [[ $# -ge 2 && "$2" != -* ]] || die "restore needs a mailbox PATH right after it, e.g. revdoku restore notes.md --version-id ID --mailbox-id ID"; ACTION="restore_version"; READ_FILE_PATH="$2"; shift 2 ;;
          append)         [[ $# -ge 2 && "$2" != -* ]] || die "append needs a mailbox PATH right after it, e.g. revdoku append leads.csv --mailbox-id ID --content-file new.csv"; ACTION="append_text_file"; APPEND_TEXT_PATH="$2"; shift 2 ;;
          archive)        ACTION="archive_mailbox"; shift ;;
          unarchive)      ACTION="unarchive_mailbox"; shift ;;
          delete)         ACTION="delete_mailbox"; shift ;;
          account)
            shift
            if [[ "${1:-}" == "create-client" ]]; then
              [[ $# -ge 2 && -n "$2" && "$2" != -* ]] || die "account create-client needs a name"
              ACTION="create_client_account"; CLIENT_ACCOUNT_NAME="$2"; shift 2
            elif [[ "${1:-}" == "limits" ]]; then
              ACTION="account_limits"; shift
            elif [[ "${1:-}" == "get" ]]; then
              [[ $# -ge 2 && "$2" =~ ^acct_[A-Za-z0-9]+$ ]] || die "account get needs an account id"
              ACTION="get_account"; ACCOUNT_DETAILS_ID="$2"; shift 2
            else
              ACTION="account_status"
            fi
            ;;
          dashboard)      ACTION="open_dashboard"; shift ;;
          help)           usage; exit 0 ;;
          version)        printf '%s\n' "$(installed_client_version)"; exit 0 ;;
          *)
            # An existing or path-like token selects files to store.
            if [[ -e "$1" || "$1" == .* || "$1" == /* || "$1" == \~* ]]; then
              PATH_TO_STORE="$1"
              PATH_EXPLICIT="true"
              shift
            else
              die "unknown command: $1 (run 'revdoku --help')"
            fi
            ;;
        esac
      fi
      ;;
  esac
done

# No arguments shows status + a hint. Uploads always require an explicit path.
if [[ "$VERB_SEEN" == "false" && "$ACTION" == "store" && "$LOGIN" != "true" ]]; then
  if [[ "$ORIGINAL_ARGC" -eq 0 ]]; then
    ACTION="connection_status"
    SHOW_UPLOAD_HINT="true"
  fi
fi

if [[ -z "$PATH_TO_STORE" ]]; then
  if [[ -n "${1:-}" ]]; then
    PATH_TO_STORE="$1"
    PATH_EXPLICIT="true"
  else
    PATH_TO_STORE="."
  fi
fi
BASE_URL="${BASE_URL%/}"
validate_base_url
if [[ "$ACTION" == "store" && "$LOGIN" != "true" && "$PATH_EXPLICIT" != "true" ]]; then
  die "upload requires an explicit PATH; use 'revdoku upload .' for this folder"
fi
[[ "$DRY_RUN" != "true" || ( "$ACTION" == "store" && "$LOGIN" != "true" ) ]] || die "--dry-run is only available with upload PATH"
[[ -z "$DELETE_CONFIRMATION" || "$ACTION" == "delete_mailbox" || "$ACTION" == "email-delete" || "$ACTION" == "webhook-delete" ]] || die "--confirm-delete is only available with delete, email-delete or webhook-delete"
if [[ ( -n "$WEBHOOK_URL" || "$ROTATE_SECRET" == "true" ) && "$ACTION" != "webhook-set" ]]; then
  die "--webhook-url and --rotate-secret require webhook-set"
fi
if [[ -n "$EMAIL_TO$EMAIL_CC$EMAIL_ATTACHMENTS$EMAIL_IN_REPLY_TO$EMAIL_TEXT$EMAIL_TEXT_FILE$EMAIL_HTML_FILE" && "$ACTION" != "email-send" ]]; then
  die "--to, --cc, --attach, --in-reply-to, --text, --text-file and --html-file require email-send"
fi
[[ -z "$EMAIL_DIRECTION" || "$ACTION" == "list_emails" ]] || die "--direction requires emails"
if [[ "$MAILBOX_LIST_OPTIONS" == "true" && "$ACTION" != "list_mailboxes" ]]; then
  die "--status and --query require ls or list"
fi
case "$ACTION" in
  list_mailboxes|list_files|list_emails|list_versions) ;;
  *) [[ -z "$LIST_LIMIT$LIST_CURSOR" ]] || die "--limit and --cursor require ls, files, emails or versions" ;;
esac
if [[ "$ACTION" == "restore_version" ]]; then
  VERSION_ID="${VERSION_ID:-$RESTORE_VERSION_ID}"
  [[ -n "$VERSION_ID" ]] || die "restore requires --version-id ID (see revdoku versions PATH)"
elif [[ -n "$VERSION_ID" && "$ACTION" != "read_file" ]]; then
  die "--version-id requires read or restore"
fi
if [[ -n "$EMAIL_USERNAME$EMAIL_DOMAIN" && "$ACTION" != "create_mailbox" ]]; then
  die "--username and --domain require create"
fi
if [[ -n "$MAILBOX_TITLE" && "$ACTION" != "create_mailbox" ]]; then
  die "--title requires create"
fi
if [[ "$ACTION" == "delete_mailbox" ]]; then
  [[ "$MAILBOX_EXPLICIT" == "true" && -n "$MAILBOX_ID" && -n "$ACCOUNT_ID" ]] || die "delete requires explicit --account-id and --mailbox-id"
fi
[[ -n "$AGENT_NAME" ]] || AGENT_NAME="$(detect_agent_name)"

need_cmd curl
need_cmd openssl
need_cmd base64
need_cmd find

if [[ -x "${SCRIPT_DIR}/jq" ]]; then
  JQ_BIN="${SCRIPT_DIR}/jq"
elif command -v jq >/dev/null 2>&1; then
  JQ_BIN="$(command -v jq)"
else
  die "requires jq"
fi

ACTION_REASON="$("$JQ_BIN" -rn --arg reason "$ACTION_REASON" '$reason | gsub("^\\s+|\\s+$"; "")')"
"$JQ_BIN" -en --arg reason "$ACTION_REASON" '$reason | length <= 2000' >/dev/null || die "--reason must be 2000 characters or fewer"

API_KEY_FROM_CREDENTIALS="false"
if [[ -z "$API_KEY" && -f "$CREDENTIALS_PATH" ]]; then
  [[ ! -L "$CREDENTIALS_PATH" ]] || die "refusing symlink credentials"
  CREDENTIALS_PATH="$(local_file_path "$CREDENTIALS_PATH")"
  [[ ! -L "$CREDENTIALS_PATH" ]] || die "refusing symlink credentials"
  API_KEY_FROM_CREDENTIALS="true"
  if [[ "$DRY_RUN" != "true" ]]; then
    API_KEY="$(tr -d '\r\n' < "$CREDENTIALS_PATH")"
  fi
fi

if [[ -z "$MAILBOX_ID" && "$API_KEY_FROM_CREDENTIALS" == "true" && -f "$DEFAULT_MAILBOX_PATH" ]]; then
  [[ ! -L "$DEFAULT_MAILBOX_PATH" ]] || die "refusing symlink mailbox selection"
  MAILBOX_ID="$(tr -d '\r\n' < "$DEFAULT_MAILBOX_PATH")"
fi

# A .revdoku file binds this folder to a mailbox for upload/read commands.
# An explicit --mailbox-id takes precedence. The binding is excluded from uploads.
if [[ -d "$PATH_TO_STORE" || ! -e "$PATH_TO_STORE" ]]; then
  REVDOKU_PROJECT_FILE="${PATH_TO_STORE%/}/.revdoku"
else
  REVDOKU_PROJECT_FILE="$(dirname "$PATH_TO_STORE")/.revdoku"
fi
[[ ! -L "$REVDOKU_PROJECT_FILE" ]] || die "refusing symlink project binding"
if [[ -f "$REVDOKU_PROJECT_FILE" ]]; then
  BINDING_EXISTED="true"
  if [[ "$MAILBOX_EXPLICIT" != "true" ]] && LC_ALL=C grep -q '^bucket_id=' "$REVDOKU_PROJECT_FILE"; then
    die "Replace bucket_id with mailbox_id in .revdoku, or use --mailbox-id."
  fi
  BOUND_MAILBOX_ID="$(sed -n 's/^mailbox_id=//p' "$REVDOKU_PROJECT_FILE" 2>/dev/null | head -n1 | tr -d '\r')"
fi
if [[ -z "$MAILBOX_ID" && -n "$BOUND_MAILBOX_ID" ]]; then
  MAILBOX_ID="$BOUND_MAILBOX_ID"
fi
[[ -z "$MAILBOX_ID" ]] || validate_id mailbox_id "$MAILBOX_ID"
[[ -z "$ACCOUNT_ID" ]] || validate_id account_id "$ACCOUNT_ID"
[[ -z "$VERSION_ID" ]] || validate_id version_id "$VERSION_ID"
for header_value in "$API_KEY" "$AGENT_NAME" "$AGENT_CLIENT" "$AGENT_VERSION" "$AGENT_RUN_ID" "$AGENT_PROJECT" "$AGENT_TASK"; do
  [[ "$header_value" != *[[:cntrl:]]* ]] || die "control characters are not allowed in request headers"
done
# Persist (or refresh) the .revdoku binding for a directory project after a
# successful upload. Silent unless it is the first time we bind.
write_project_binding() {
  local mailbox="$1" url="$2"
  [[ "${REVDOKU_WRITE_BINDING:-true}" == "true" ]] || return 0
  [[ -n "$mailbox" && -n "$REVDOKU_PROJECT_FILE" ]] || return 0
  [[ -d "$PATH_TO_STORE" ]] || return 0
  {
    printf '# Revdoku project binding — created by `revdoku upload`. Safe to commit or gitignore.\n'
    printf 'mailbox_id=%s\n' "$mailbox"
    if [[ -n "$url" ]]; then printf 'url=%s\n' "$url"; fi
  } | atomic_private_write "$REVDOKU_PROJECT_FILE" || return 1
  if [[ "$BINDING_EXISTED" != "true" ]]; then
    echo "Bound this folder to $mailbox (.revdoku). Next time just run: revdoku upload ." >&2
    BINDING_EXISTED="true"
  fi
}

if [[ -n "$METADATA_JSON" ]]; then
  METADATA_JSON="$(printf "%s" "$METADATA_JSON" | "$JQ_BIN" -c 'if type == "object" then . else error("metadata must be a JSON object") end')" || die "--metadata must be a JSON object"
else
  METADATA_JSON="{}"
fi

normalize_optional_bool() {
  local name="$1"
  local value="$2"
  [[ -n "$value" ]] || return 0
  case "$value" in
    true|1|yes|on)
      printf "true"
      ;;
    false|0|no|off)
      printf "false"
      ;;
    *)
      die "$name must be true or false"
      ;;
  esac
}

APPEND_TEXT_NEWLINE_BEFORE="$(normalize_optional_bool "REVDOKU_APPEND_TEXT_NEWLINE_BEFORE" "$APPEND_TEXT_NEWLINE_BEFORE")"
APPEND_TEXT_NEWLINE_BEFORE="${APPEND_TEXT_NEWLINE_BEFORE:-true}"

if [[ "$ACTION" == "append_text_file" ]]; then
  [[ -n "$MAILBOX_ID" ]] || die "append requires --mailbox-id"
  [[ -n "$APPEND_TEXT_PATH" ]] || die "append requires a mailbox-relative PATH"
  if [[ -n "$APPEND_TEXT_CONTENT" && -n "$APPEND_TEXT_CONTENT_FILE" ]]; then
    die "use either --content or --content-file with append, not both"
  fi
  if [[ -z "$APPEND_TEXT_CONTENT" && -z "$APPEND_TEXT_CONTENT_FILE" ]]; then
    die "append requires --content or --content-file"
  fi
fi

account_request_path() {
  local request_path="$1" separator="?"
  if [[ -n "$ACCOUNT_ID" && "$request_path" == /api/v1/* ]]; then
    [[ "$request_path" != *\?* ]] || separator="&"
    printf '%s%saccount_id=%s' "$request_path" "$separator" "$("$JQ_BIN" -rn --arg id "$ACCOUNT_ID" '$id|@uri')"
  else
    printf '%s' "$request_path"
  fi
}

api_url() {
  [[ "$1" == /* && "$1" != //* && "$1" != *[[:space:][:cntrl:]\\]* && "$1" != *'#'* ]] || die "invalid API path"
  if [[ "$BASE_URL" == "$DEFAULT_URL" && "$1" == /api/v1/* ]]; then
    printf "%s%s" "$BASE_URL" "${1#/api}"
  else
    printf "%s%s" "$APP_URL" "$1"
  fi
}

json_string() {
  "$JQ_BIN" -rn --arg value "$1" '$value'
}

http_status_success() {
  local status="${1:-}"
  [[ "$status" =~ ^[0-9]+$ ]] && (( status >= 200 && status < 300 ))
}

http_status_retryable() {
  case "${1:-}" in
    408|425|429|500|502|503|504)
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}

http_error_code_retryable() {
  case "${1:-}" in
    DATABASE_BUSY_RETRY|MAILBOX_DELETE_BUSY|MAILBOX_DELETE_ENQUEUE_FAILED)
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}

retry_delay_for_attempt() {
  local attempt="${1:-1}"
  local retry_after="${2:-}"
  local delay
  if [[ "$retry_after" =~ ^[0-9]+$ && "$retry_after" -gt 0 ]]; then
    echo "$retry_after"
    return 0
  fi
  case "$attempt" in
    1) delay=1 ;;
    2) delay=2 ;;
    3) delay=4 ;;
    *) delay=8 ;;
  esac
  echo "$delay"
}

http_success_json_replay_allowed() {
  local method="$1"
  local path="$2"
  case "$method:$path" in
    GET:*)
      return 0
      ;;
    POST:*/upload_sessions|POST:*/upload_sessions/*/uploads|POST:*/upload_sessions/*/finalize|POST:*/upload_sessions/*/finalize_batch)
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}

http_conflict_retry_allowed() {
  local method="$1"
  local path="$2"
  case "$method:$path" in
    GET:*)
      return 0
      ;;
    POST:*/upload_sessions|POST:*/upload_sessions/*/uploads|POST:*/upload_sessions/*/finalize|POST:*/upload_sessions/*/finalize_batch)
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}

http_lock_retry_allowed() {
  local method="$1"
  local path="$2"
  case "$method:$path" in
    POST:*/files/append_text)
      return 0
      ;;
    *)
      return 1
      ;;
  esac
}

lock_detail_summary() {
  local details_json="${1:-{}}"
  "$JQ_BIN" -r '
    def present: select(. != null and . != "");
    (.locked_by_api_key.label // .locked_by.name // .locked_by.email // .locked_by_api_key.id // .locked_by.id // "another actor") as $owner
    | (.message // .kind // "" | tostring) as $message
    | (.locked_until // "" | tostring) as $until
    | "locked by " + $owner
      + (if ($message | length) > 0 then " (" + $message + ")" else "" end)
      + (if ($until | length) > 0 then " until " + $until else "" end)
  ' <<<"$details_json" 2>/dev/null || printf 'locked by another actor'
}

agent_header_args() {
  printf "%s\0" \
    "-H" "User-Agent: Revdoku/${AGENT_VERSION} (${AGENT_CLIENT})" \
    "-H" "X-Revdoku-Agent: ${AGENT_NAME}" \
    "-H" "X-Revdoku-Agent-Client: ${AGENT_CLIENT}" \
    "-H" "X-Revdoku-Agent-Version: ${AGENT_VERSION}"
  [[ -n "$AGENT_RUN_ID" ]] && printf "%s\0" "-H" "X-Revdoku-Agent-Run-Id: ${AGENT_RUN_ID}"
  [[ -n "$AGENT_PROJECT" ]] && printf "%s\0" "-H" "X-Revdoku-Agent-Project: ${AGENT_PROJECT}"
  [[ -n "$AGENT_TASK" ]] && printf "%s\0" "-H" "X-Revdoku-Agent-Task: ${AGENT_TASK}"
}

reason_request_path() {
  local path="$1" separator="?"
  if [[ -n "$ACTION_REASON" ]]; then
    [[ "$path" != *\?* ]] || separator="&"
    path="${path}${separator}reason=$("$JQ_BIN" -rn --arg value "$ACTION_REASON" '$value | @uri')"
  fi
  printf '%s' "$path"
}

http_json() {
  local method="$1"
  local path="$2"
  local payload="$3"
  local auth="${4:-true}"
  local HTTP_TRANSIENT_MAX_ATTEMPTS="$HTTP_TRANSIENT_MAX_ATTEMPTS"
  [[ "$method" != "DELETE" ]] || HTTP_TRANSIENT_MAX_ATTEMPTS=0
  # Creation has no replay key. A lost or failed response may follow a commit.
  if [[ "$method" == "POST" && "$path" == "/api/v1/mailboxes" ]]; then
    HTTP_TRANSIENT_MAX_ATTEMPTS=0
  fi
  # Never send an email twice. Rate limits also return without a retry.
  local send_once="false"
  if [[ "$method" == "POST" && "$path" =~ ^/api/v1/mailboxes/[^/?]+/emails$ ]]; then
    HTTP_TRANSIENT_MAX_ATTEMPTS=0
    send_once="true"
  fi
  if [[ -n "$ACCOUNT_ID" && "$auth" == "true" && "$path" == /api/v1/* ]]; then
    if [[ "$method" == "GET" || "$method" == "HEAD" ]]; then
      path="$(account_request_path "$path")"
    else
      payload="$("$JQ_BIN" -c --arg account_id "$ACCOUNT_ID" '. + {account_id: $account_id}' <<<"$payload")"
    fi
  fi
  if [[ -n "$ACTION_REASON" && "$auth" == "true" && "$path" == /api/v1/* ]]; then
    if [[ "$method" == "GET" || "$method" == "HEAD" ]]; then
      path="$(reason_request_path "$path")"
    else
      payload="$("$JQ_BIN" -c --arg reason "$ACTION_REASON" '. + {reason: $reason}' <<<"$payload")"
    fi
  fi
  local body_file status message code request_id retry_after details_json upgrade_url attempt curl_status delay agent_args=()
  LAST_HTTP_STATUS=""
  LAST_ERROR_CODE=""
  LAST_ERROR_MESSAGE=""
  LAST_ERROR_DETAILS_JSON=""
  body_file="$(mktemp)"
  attempt=0

  while IFS= read -r -d '' value; do
    agent_args+=("$value")
  done < <(agent_header_args)

  local args=(-sS -o "$body_file" -w "%{http_code}" -X "$method" --url "$(api_url "$path")" "${agent_args[@]}" -H "Content-Type: application/json")
  if [[ "$auth" == "true" ]]; then
    args+=(-H "Authorization: Bearer $API_KEY")
  fi
  # Read the body from stdin: one command-line argument is limited to 128 KiB on Linux.
  args+=(--data-binary @-)

  while true; do
    : > "$body_file"
    if status="$(printf '%s' "$payload" | safe_curl "${args[@]}")"; then
      curl_status=0
    else
      curl_status=$?
      if (( attempt < HTTP_TRANSIENT_MAX_ATTEMPTS )); then
        attempt=$((attempt + 1))
        delay="$(retry_delay_for_attempt "$attempt")"
        echo "Network error while calling $path; retrying in ${delay}s (${attempt}/${HTTP_TRANSIENT_MAX_ATTEMPTS})..." >&2
        sleep "$delay"
        continue
      fi
      rm -f "$body_file"
      LAST_HTTP_STATUS=""
      LAST_ERROR_CODE=""
      LAST_ERROR_MESSAGE="Network error while calling $path"
      LAST_ERROR_DETAILS_JSON=""
      echo "error: network error while calling $path (curl exit $curl_status)" >&2
      return 1
    fi

    if http_status_success "$status"; then
      if [[ "$status" != "204" ]] && ! "$JQ_BIN" -e . "$body_file" >/dev/null 2>&1; then
        if http_success_json_replay_allowed "$method" "$path" && (( attempt < HTTP_TRANSIENT_MAX_ATTEMPTS )); then
          attempt=$((attempt + 1))
          delay="$(retry_delay_for_attempt "$attempt")"
          echo "Invalid JSON response from $path after HTTP $status; retrying in ${delay}s (${attempt}/${HTTP_TRANSIENT_MAX_ATTEMPTS})..." >&2
          sleep "$delay"
          continue
        fi
        rm -f "$body_file"
        LAST_HTTP_STATUS="$status"
        LAST_ERROR_CODE="INVALID_JSON_RESPONSE"
        LAST_ERROR_MESSAGE="Invalid JSON response from $path after HTTP $status"
        LAST_ERROR_DETAILS_JSON=""
        echo "error: invalid JSON response from $path after HTTP $status" >&2
        return 1
      fi
      cat "$body_file"
      rm -f "$body_file"
      return 0
    fi

    message="$("$JQ_BIN" -r '.error.message // .error_description // .message // empty' "$body_file" 2>/dev/null || true)"
    code="$("$JQ_BIN" -r '.error.code // .error // empty' "$body_file" 2>/dev/null || true)"
    request_id="$("$JQ_BIN" -r '.error.request_id // .request_id // empty' "$body_file" 2>/dev/null || true)"
    retry_after="$("$JQ_BIN" -r '.error.details.retry_after // empty' "$body_file" 2>/dev/null || true)"
    details_json="$("$JQ_BIN" -c '.error.details // {}' "$body_file" 2>/dev/null || printf '{}')"

    # Plan limits also answer 429 (for example MAILBOX_CREATION_LIMIT_REACHED); only rate limits clear on retry.
    if [[ "$method" != "DELETE" && "$send_once" != "true" && "$status" == "429" && "$attempt" -lt 20 ]] &&
      [[ -z "$code" || "$code" == *RATE_LIMIT* ]]; then
      [[ "$retry_after" =~ ^[0-9]+$ && "$retry_after" -gt 0 ]] || retry_after=5
      attempt=$((attempt + 1))
      echo "Rate limited while calling $path; retrying in ${retry_after}s..." >&2
      sleep "$retry_after"
      continue
    fi

    if [[ "$method" != "DELETE" && "$status" == "409" ]] && http_error_code_retryable "$code" && http_conflict_retry_allowed "$method" "$path" && (( attempt < HTTP_RETRYABLE_CONFLICT_MAX_ATTEMPTS )); then
      attempt=$((attempt + 1))
      delay="$(retry_delay_for_attempt "$attempt" "$retry_after")"
      echo "Server is busy while calling $path; retrying in ${delay}s (${attempt}/${HTTP_RETRYABLE_CONFLICT_MAX_ATTEMPTS})..." >&2
      sleep "$delay"
      continue
    fi

    if [[ "$status" == "423" && ( "$code" == "MAILBOX_LOCKED" || "$code" == "FILE_LOCKED" ) ]] && http_lock_retry_allowed "$method" "$path" && (( attempt < HTTP_LOCK_MAX_ATTEMPTS )); then
      attempt=$((attempt + 1))
      delay="$(retry_delay_for_attempt "$attempt" "$retry_after")"
      echo "Locked while calling $path ($(lock_detail_summary "$details_json")); retrying in ${delay}s (${attempt}/${HTTP_LOCK_MAX_ATTEMPTS})..." >&2
      sleep "$delay"
      continue
    fi

    if http_status_retryable "$status" && (( attempt < HTTP_TRANSIENT_MAX_ATTEMPTS )); then
      attempt=$((attempt + 1))
      delay="$(retry_delay_for_attempt "$attempt")"
      echo "Transient HTTP $status while calling $path; retrying in ${delay}s (${attempt}/${HTTP_TRANSIENT_MAX_ATTEMPTS})..." >&2
      sleep "$delay"
      continue
    fi

    rm -f "$body_file"
    LAST_HTTP_STATUS="$status"
    LAST_ERROR_CODE="$code"
    LAST_ERROR_MESSAGE="$message"
    LAST_ERROR_DETAILS_JSON="$details_json"
    [[ -n "$message" ]] || message="HTTP $status"
    [[ -n "$code" ]] && message="${message} (${code})"
    [[ -n "$request_id" ]] && message="${message} request_id=${request_id}"
    echo "error: $message" >&2
    upgrade_url="$("$JQ_BIN" -r '.upgrade_url? // empty | strings | select(test("^https?://[^\\s\\p{Cc}]+$"))' <<<"$details_json" 2>/dev/null || true)"
    [[ -z "$upgrade_url" ]] || echo "Upgrade: $upgrade_url" >&2
    if [[ "$status" == "423" && ( "$code" == "MAILBOX_LOCKED" || "$code" == "FILE_LOCKED" ) ]]; then
      echo "Lock details: $(lock_detail_summary "$details_json")" >&2
    fi
    if [[ "$auth" == "true" ]]; then
      if [[ "$code" == "ACCOUNT_ACCESS_UNAVAILABLE" ]]; then
        echo "This connection uses mailbox-scoped agent credentials, which cannot read account-level status. Verify the connection with 'revdoku status', or open Revdoku in a browser for account details." >&2
      elif [[ "$status" == "401" || "$status" == "403" ]]; then
        echo "Run 'revdoku login' to reconnect and save a fresh Revdoku API key." >&2
      fi
    fi
    return 1
  done
}

http_json_quiet() {
  local method="$1"
  local path="$2"
  local payload="$3"
  local body_file status message code agent_args=()
  LAST_HTTP_STATUS=""
  LAST_ERROR_CODE=""
  LAST_ERROR_MESSAGE=""
  LAST_ERROR_DETAILS_JSON=""
  body_file="$(mktemp)"

  while IFS= read -r -d '' value; do
    agent_args+=("$value")
  done < <(agent_header_args)

  if ! status="$(safe_curl -sS -o "$body_file" -w "%{http_code}" -X "$method" --url "$(api_url "$path")" "${agent_args[@]}" -H "Content-Type: application/json" --data "$payload")"; then
    rm -f "$body_file"
    LAST_HTTP_STATUS=""
    LAST_ERROR_CODE="NETWORK_ERROR"
    LAST_ERROR_MESSAGE="Network error while calling $path"
    LAST_ERROR_DETAILS_JSON=""
    return 1
  fi

  if http_status_success "$status"; then
    cat "$body_file"
    rm -f "$body_file"
    return 0
  fi

  message="$("$JQ_BIN" -r 'if (.error | type) == "object" then (.error.message // empty) else (.error_description // .message // empty) end' "$body_file" 2>/dev/null || true)"
  code="$("$JQ_BIN" -r 'if (.error | type) == "object" then (.error.code // empty) else (.error // empty) end' "$body_file" 2>/dev/null || true)"
  LAST_HTTP_STATUS="$status"
  LAST_ERROR_CODE="$code"
  LAST_ERROR_MESSAGE="$message"
  LAST_ERROR_DETAILS_JSON="$("$JQ_BIN" -c 'if (.error | type) == "object" then (.error.details // {}) else {} end' "$body_file" 2>/dev/null || printf '{}')"
  rm -f "$body_file"
  return 1
}

prompt_read() {
  local prompt="$1"
  local value
  if [[ -t 0 ]]; then
    printf "%s" "$prompt" >&2
    IFS= read -r value
  elif { exec 3<>/dev/tty; } 2>/dev/null; then
    printf "%s" "$prompt" >&3
    IFS= read -r value <&3
    exec 3>&-
  else
    die "Browser login could not start, and the email-code fallback needs an interactive terminal. Retry 'revdoku login' in a terminal."
  fi
  printf "%s" "$value"
}

save_api_key() {
  local key="$1"
  [[ -n "$key" ]] || die "API key is required"
  [[ "$key" != *[[:cntrl:]]* ]] || die "invalid credential"
  printf "%s\n" "$key" | atomic_private_write "$CREDENTIALS_PATH" || return 1
  rm -f "$DEFAULT_MAILBOX_PATH"
  echo "Saved Revdoku API key to $CREDENTIALS_PATH" >&2
  echo "This is a one-time setup. Future runs will reuse the saved key automatically." >&2
  API_KEY="$key"
}

open_browser_url() {
  local url="$1"
  validate_api_url "$url"
  if command -v open >/dev/null 2>&1; then
    open "$url" >/dev/null 2>&1 && return 0
  fi
  if command -v xdg-open >/dev/null 2>&1; then
    xdg-open "$url" >/dev/null 2>&1 && return 0
  fi
  if command -v wslview >/dev/null 2>&1; then
    wslview "$url" >/dev/null 2>&1 && return 0
  fi
  return 1
}

# Open the selected mailbox in the authenticated dashboard.
open_dashboard() {
  if [[ -n "$MAILBOX_ID" ]]; then
    BROWSER_LOGIN_PATH="/mailboxes/view?id=$MAILBOX_ID"
  else
    BROWSER_LOGIN_PATH="/mailboxes"
  fi
  browser_login_link
}

request_device_agent_key() {
  local payload response response_file client_id device_code user_code verification_uri_complete expires_in interval deadline now token_payload key signup_medium

  signup_medium=cli
  [[ "${REVDOKU_SIGNUP_MEDIUM:-}" == "skill" ]] && signup_medium=skill

  payload="$("$JQ_BIN" -nc --arg grant "$DEVICE_CODE_GRANT_TYPE" '{client_name:"Revdoku CLI", redirect_uris:[], grant_types:[$grant,"refresh_token"], response_types:[], token_endpoint_auth_method:"none"}')"
  response="$(http_json_quiet POST "/oauth/register" "$payload")" || return 1
  client_id="$("$JQ_BIN" -r '.client_id // empty' <<<"$response")"
  [[ -n "$client_id" ]] || return 1

  payload="$("$JQ_BIN" -nc --arg client_id "$client_id" --arg resource "$MCP_RESOURCE" --arg signup_medium "$signup_medium" '{client_id:$client_id, scope:"revdoku:mcp", resource:$resource, signup_medium:$signup_medium}')"
  response="$(http_json_quiet POST "/oauth/device_authorization" "$payload")" || return 1
  device_code="$("$JQ_BIN" -r '.device_code // empty' <<<"$response")"
  user_code="$("$JQ_BIN" -r '.user_code // empty' <<<"$response")"
  verification_uri_complete="$("$JQ_BIN" -r '.verification_uri_complete // .verification_uri // empty' <<<"$response")"
  expires_in="$("$JQ_BIN" -r '.expires_in // 600' <<<"$response")"
  interval="$("$JQ_BIN" -r '.interval // 5' <<<"$response")"
  [[ -n "$device_code" && -n "$user_code" && -n "$verification_uri_complete" ]] || return 1
  [[ "$expires_in" =~ ^[0-9]+$ && "$expires_in" -gt 0 ]] || expires_in=600
  [[ "$interval" =~ ^[0-9]+$ && "$interval" -gt 0 ]] || interval=5

  validate_api_url "$verification_uri_complete"
  echo "Open this Revdoku link to connect:" >&2
  echo "$verification_uri_complete" >&2
  echo "Connection ID is $user_code" >&2
  echo "This is a safety check. Make sure the same ID appears in the top-right of Revdoku, then select Connect." >&2
  if open_browser_url "$verification_uri_complete"; then
    echo "Opened the approval page in your browser." >&2
  else
    echo "Could not open a browser automatically; paste the link above into your browser." >&2
  fi
  echo "Waiting for browser approval..." >&2

  deadline=$(( $(date +%s) + expires_in ))
  response_file="$(mktemp)"
  while true; do
    now="$(date +%s)"
    if [[ "$now" =~ ^[0-9]+$ && "$now" -ge "$deadline" ]]; then
      rm -f "$response_file"
      die "device login expired; run 'revdoku login' again"
    fi

    sleep "$interval"
    token_payload="$("$JQ_BIN" -nc --arg grant "$DEVICE_CODE_GRANT_TYPE" --arg client_id "$client_id" --arg device_code "$device_code" --arg resource "$MCP_RESOURCE" '{grant_type:$grant, client_id:$client_id, device_code:$device_code, resource:$resource}')"
    : > "$response_file"
    # Keep http_json_quiet in this shell. Command substitution would run it in a
    # subshell and discard LAST_ERROR_CODE, turning the expected
    # authorization_pending response into a false legacy-login fallback.
    if http_json_quiet POST "/oauth/token" "$token_payload" > "$response_file"; then
      response="$(cat "$response_file")"
      key="$("$JQ_BIN" -r '.revdoku_api_key // empty' <<<"$response")"
      [[ -n "$key" ]] || die "device login did not return a Revdoku API key"
      save_api_key "$key" || return 1
      rm -f "$response_file"
      return 0
    fi

    case "$LAST_ERROR_CODE" in
      authorization_pending)
        ;;
      slow_down)
        interval=$((interval + 5))
        ;;
      access_denied)
        rm -f "$response_file"
        die "Revdoku connection was denied in the browser"
        ;;
      expired_token)
        rm -f "$response_file"
        die "device login expired; run 'revdoku login' again"
        ;;
      *)
        rm -f "$response_file"
        return 1
        ;;
    esac
  done
}

request_email_agent_key() {
  local email code payload response key

  while true; do
    email="$(prompt_read "Email: ")"
    [[ -n "$email" ]] || die "email is required"

    payload="$("$JQ_BIN" -nc --arg email "$email" '{email:$email}')"
    if http_json POST "/api/v1/agent_auth/request_code" "$payload" false >/dev/null; then
      break
    fi

    die "could not start email verification"
  done

  echo "If $email can receive Revdoku sign-in codes, a verification code was sent." >&2
  echo "If no code arrives, sign in at $APP_URL/users/sign_in or retry browser device sign-in with 'revdoku login'." >&2

  code="$(prompt_read "Code: ")"
  [[ -n "$code" ]] || die "code is required"

  payload="$("$JQ_BIN" -nc --arg email "$email" --arg code "$code" '{email:$email, code:$code, label:"Revdoku mailbox client"}')"
  if ! response="$(http_json POST "/api/v1/agent_auth/verify_code" "$payload" false)"; then
    die "Could not verify the code. If no code arrived or the code is rejected, use 'revdoku login' and complete browser device sign-in."
  fi
  key="$("$JQ_BIN" -r '.data.api_key // empty' <<<"$response")"
  [[ -n "$key" ]] || die "verification did not return an API key. Use 'revdoku login' and complete browser device sign-in."

  save_api_key "$key" || return 1
}

request_agent_key() {
  if request_device_agent_key; then
    return
  fi

  echo "Browser device login is unavailable on this Revdoku server; using legacy email-code fallback." >&2
  request_email_agent_key
}

exchange_agent_grant() {
  local token="$1" payload response key account_id account_name
  [[ -n "$token" ]] || die "one-time connection token is required"
  payload="$("$JQ_BIN" -nc --arg grant_token "$token" --arg label "${AGENT_NAME} connection" '{grant_token:$grant_token,label:$label}')"
  response="$(http_json POST "/api/v1/agent_auth/exchange_grant" "$payload" false)" \
    || die "connection token is invalid, expired, or already used"
  key="$("$JQ_BIN" -r '.data.api_key // empty' <<<"$response")"
  account_id="$("$JQ_BIN" -r '.data.account_id // empty' <<<"$response")"
  account_name="$("$JQ_BIN" -r '.data.account_name // empty' <<<"$response")"
  [[ -n "$key" ]] || die "connection response did not include an API key"
  save_api_key "$key" || return 1
  echo "Connected to Revdoku${account_name:+: $account_name}." >&2
  [[ -n "$account_id" ]] && echo "Account: $account_id" >&2
}

if [[ "$DRY_RUN" != "true" ]]; then
  if [[ "$ACTION" == "exchange_grant" ]]; then
    exchange_agent_grant "$GRANT_TOKEN"
    echo "Connection complete. You can return to your AI agent." >&2
    exit 0
  fi

  # Bare `revdoku` with no saved credentials: show a friendly hint instead of
  # forcing the interactive login flow.
  if [[ "$ACTION" == "connection_status" && "$SHOW_UPLOAD_HINT" == "true" && -z "$API_KEY" ]]; then
    echo "Revdoku CLI — not signed in yet." >&2
    echo "  Sign in:   revdoku login" >&2
    echo "  Upload:    revdoku upload PATH" >&2
    echo "  Commands:  revdoku --help" >&2
    exit 0
  fi

  if [[ "$LOGIN" == "true" || -z "$API_KEY" ]]; then
    request_agent_key
  fi

  if [[ "$LOGIN" == "true" && "$ACTION" == "store" && "$PATH_EXPLICIT" == "false" ]]; then
    echo "Login complete. Credentials saved to $CREDENTIALS_PATH." >&2
    echo "Next: revdoku upload PATH, or revdoku dashboard." >&2
    exit 0
  fi

  [[ -n "$API_KEY" ]] || die "REVDOKU_API_KEY is required"
  case "$UPLOAD_MODE" in
    auto|direct) ;;
    *) die "--upload-mode must be auto or direct" ;;
  esac
fi # network authentication is skipped by upload --dry-run
# Build "name=value&..." from name/value pairs, omitting empty values.
query_string() {
  "$JQ_BIN" -rn '$ARGS.positional | [range(0; length; 2) as $i | {key: .[$i], value: .[$i + 1]}]
    | map(select(.value != "") | (.key + "=" + (.value | @uri))) | join("&")' --args "$@"
}

list_mailboxes() {
  http_json GET "/api/v1/mailboxes?$(query_string status "$MAILBOX_LIST_STATUS" q "$MAILBOX_LIST_QUERY" limit "$LIST_LIMIT" cursor "$LIST_CURSOR")" "{}"
}

list_files() {
  [[ -n "$MAILBOX_ID" ]] || die "files requires --mailbox-id (or a remembered selected mailbox)"
  local query
  query="$(query_string limit "$LIST_LIMIT" cursor "$LIST_CURSOR")"
  http_json GET "/api/v1/mailboxes/${MAILBOX_ID}/files${query:+?$query}" "{}"
}

# Prints the ID of the current file at READ_FILE_PATH, or the given df_ file ID.
file_id_for_path() {
  local response id
  if [[ "$READ_FILE_PATH" =~ ^df_[A-Za-z0-9]+$ ]]; then
    printf '%s' "$READ_FILE_PATH"
    return 0
  fi
  response="$(http_json GET "/api/v1/mailboxes/${MAILBOX_ID}/files/by_path?$(query_string path "$READ_FILE_PATH")" "{}")" || return 1
  id="$("$JQ_BIN" -r '.data.file.id // empty' <<<"$response")"
  validate_id file_id "$id"
  printf '%s' "$id"
}

list_versions() {
  [[ -n "$MAILBOX_ID" ]] || die "versions requires --mailbox-id"
  local file_id query
  file_id="$(file_id_for_path)" || return 1
  query="$(query_string limit "$LIST_LIMIT" cursor "$LIST_CURSOR")"
  http_json GET "/api/v1/mailboxes/${MAILBOX_ID}/files/${file_id}/versions${query:+?$query}" "{}"
}

restore_version() {
  [[ -n "$MAILBOX_ID" ]] || die "restore requires --mailbox-id"
  local file_id
  file_id="$(file_id_for_path)" || return 1
  http_json POST "/api/v1/mailboxes/${MAILBOX_ID}/files/${file_id}/versions/${VERSION_ID}/restore" "{}"
}

# Content reads use a temporary link. Downloading marks the version read.
read_file() {
  [[ -n "$MAILBOX_ID" && -n "$READ_FILE_PATH" ]] || die "read requires a mailbox and PATH"
  local file_id query response
  file_id="$(file_id_for_path)" || return 1
  query="$(query_string version_id "$VERSION_ID")"
  response="$(http_json GET "/api/v1/mailboxes/${MAILBOX_ID}/files/${file_id}/download${query:+?$query}" "{}")" || return 1
  download_link "$response" "$READ_FILE_PATH"
}

# Fetch data.download.url from an API response. The link carries its own
# authorization: never send the API key to it.
download_link() {
  local response="$1" label="$2" url
  url="$("$JQ_BIN" -er '.data.download.url' <<<"$response")" || die "download response did not include url"
  download_file_url "$url" "$label"
}

# Follow downloads one hop at a time so each destination is checked before use.
download_file_url() {
  local url="$1" label="$2" body_file headers status location hop
  body_file="$(mktemp)"
  headers="$(mktemp)"
  for hop in 0 1 2 3 4 5; do
    if ! validate_transfer_url "$url"; then
      rm -f "$body_file" "$headers"
      die "download destination is not approved"
    fi
    if ! status="$(safe_curl -sS --max-time 120 -D "$headers" -o "$body_file" -w "%{http_code}" \
      -H "Accept: */*" --url "$url")"; then
      rm -f "$body_file" "$headers"
      die "network error while reading file"
    fi
    case "$status" in
      301|302|303|307|308)
        location="$(awk 'tolower($1) == "location:" {sub(/^[^:]*:[ \t]*/, ""); sub(/\r$/, ""); print}' "$headers")"
        [[ "$location" != /* || "$location" == //* ]] || location="${url%%://*}://$(printf '%s' "${url#*://}" | cut -d/ -f1)$location"
        url="$location"
        ;;
      2??)
        rm -f "$headers"
        if [[ -n "$OUTPUT_PATH" ]]; then
          if ! atomic_private_write "$OUTPUT_PATH" < "$body_file"; then
            rm -f "$body_file"
            return 1
          fi
          echo "Saved $label to $OUTPUT_PATH" >&2
        else
          cat "$body_file"
        fi
        rm -f "$body_file"
        return 0
        ;;
      *)
        rm -f "$body_file" "$headers"
        die "failed to read file (HTTP $status)"
        ;;
    esac
  done
  rm -f "$body_file" "$headers"
  die "too many file download redirects"
}

email_command() {
  [[ -n "$MAILBOX_ID" ]] || die "email commands require --mailbox-id or a bound folder"
  local path="/api/v1/mailboxes/${MAILBOX_ID}/emails" query response
  if [[ "$ACTION" == "list_emails" ]]; then
    query="$(query_string limit "$LIST_LIMIT" cursor "$LIST_CURSOR" direction "$EMAIL_DIRECTION" sender "$EMAIL_SENDER" \
      subject "$EMAIL_SUBJECT" conversation_id "$EMAIL_CONVERSATION" read "$EMAIL_READ")"
    http_json GET "${path}${query:+?$query}" "{}"
    return
  fi
  if [[ "$ACTION" == "email-send" ]]; then
    send_email "$path"
    return
  fi
  [[ "$EMAIL_ID" =~ ^eml_[A-Za-z0-9]+$ ]] || die "invalid email id"
  path="${path}/${EMAIL_ID}"
  case "$ACTION" in
    email)
      http_json GET "$path" "{}"
      ;;
    email-status)
      [[ -n "$EMAIL_READ" ]] || die "email-status requires --read true|false"
      http_json PATCH "$path" "$("$JQ_BIN" -nc --argjson read "$EMAIL_READ" '{read:$read}')"
      ;;
    email-delete)
      [[ "$DELETE_CONFIRMATION" == "$EMAIL_ID" ]] || die "To delete this email and its attachments, repeat with --confirm-delete $EMAIL_ID"
      http_json DELETE "$path" "{}"
      ;;
    email-download)
      if [[ -n "$EMAIL_ATTACHMENT_ID" ]]; then
        [[ "$EMAIL_ATTACHMENT_ID" =~ ^df_[A-Za-z0-9]+$ ]] || die "invalid attachment id"
        path="${path}/attachments/${EMAIL_ATTACHMENT_ID}"
      else
        path="${path}/raw"
      fi
      response="$(http_json GET "$path" "{}")" || return 1
      download_link "$response" "$("$JQ_BIN" -r '.data.download.filename // "download"' <<<"$response")"
      ;;
  esac
}

# The server checks recipients, limits and permissions.
send_email() {
  local path="$1" text_file html_file payload
  [[ -n "$EMAIL_TEXT" || -n "$EMAIL_TEXT_FILE" ]] || die "email-send requires --text TEXT or --text-file PATH"
  [[ -z "$EMAIL_TEXT" || -z "$EMAIL_TEXT_FILE" ]] || die "Use --text or --text-file, not both"
  [[ -z "$EMAIL_TEXT_FILE" || "$EMAIL_TEXT_FILE" == "-" || -f "$EMAIL_TEXT_FILE" ]] || die "--text-file does not exist: $EMAIL_TEXT_FILE"
  [[ -z "$EMAIL_HTML_FILE" || -f "$EMAIL_HTML_FILE" ]] || die "--html-file does not exist: $EMAIL_HTML_FILE"
  # Bodies go through files: Linux limits one argument to 128 KiB.
  text_file="$(mktemp)"; html_file="$(mktemp)"
  # Expand now: the EXIT trap runs after these locals leave scope.
  trap "rm -f $(printf '%q ' "$text_file" "$html_file")" EXIT
  if [[ "$EMAIL_TEXT_FILE" == "-" ]]; then
    cat > "$text_file"
  elif [[ -n "$EMAIL_TEXT_FILE" ]]; then
    cat "$EMAIL_TEXT_FILE" > "$text_file"
  else
    printf "%s" "$EMAIL_TEXT" > "$text_file"
  fi
  [[ -z "$EMAIL_HTML_FILE" ]] || cat "$EMAIL_HTML_FILE" > "$html_file"
  payload="$("$JQ_BIN" -nc --rawfile text "$text_file" --rawfile html "$html_file" \
    --arg to "$EMAIL_TO" --arg cc "$EMAIL_CC" --arg attachments "$EMAIL_ATTACHMENTS" \
    --arg subject "$EMAIL_SUBJECT" --arg in_reply_to "$EMAIL_IN_REPLY_TO" '
    def list: split("\n") | map(select(. != ""));
    {to: ($to | list), cc: ($cc | list), subject: $subject, text: $text, html: (if $html == "" then null else $html end),
      in_reply_to: $in_reply_to, attachment_ids: ($attachments | list)}
    | with_entries(select(.value != null and .value != "" and .value != []))')" || payload=""
  rm -f "$text_file" "$html_file"
  [[ -n "$payload" ]] || die "Could not read the email body"
  if ! http_json POST "$path" "$payload"; then
    if [[ -z "$LAST_HTTP_STATUS" || "$LAST_HTTP_STATUS" == 5* ]]; then
      echo "The send result is unknown. Do not send again until 'revdoku emails --direction sent --mailbox-id $MAILBOX_ID' confirms it was not sent." >&2
    fi
    return 1
  fi
}

create_mailbox() {
  local payload
  payload="$("$JQ_BIN" -nc --arg description "$DESCRIPTION" --arg title "$MAILBOX_TITLE" \
    --arg username "$EMAIL_USERNAME" --arg domain "$EMAIL_DOMAIN" \
    --argjson metadata "$METADATA_JSON" \
    '{mailbox: (({title:$title,description:$description} | with_entries(select(.value != ""))) +
      (if ($metadata | length) > 0 then {metadata: $metadata} else {} end) +
      {email: ({username:$username,domain:$domain} | with_entries(select(.value != "")))})}')"
  http_json POST "/api/v1/mailboxes" "$payload"
}

append_text_file() {
  local content_file tmp_content payload response path
  [[ -n "$MAILBOX_ID" ]] || die "append requires --mailbox-id"
  [[ -n "$APPEND_TEXT_PATH" ]] || die "append requires a mailbox-relative PATH"

  tmp_content=""
  if [[ -n "$APPEND_TEXT_CONTENT_FILE" ]]; then
    if [[ "$APPEND_TEXT_CONTENT_FILE" == "-" ]]; then
      tmp_content="$(mktemp)"
      cat > "$tmp_content"
      content_file="$tmp_content"
    else
      [[ -f "$APPEND_TEXT_CONTENT_FILE" ]] || die "--content-file does not exist: $APPEND_TEXT_CONTENT_FILE"
      content_file="$APPEND_TEXT_CONTENT_FILE"
    fi
  else
    tmp_content="$(mktemp)"
    printf "%s" "$APPEND_TEXT_CONTENT" > "$tmp_content"
    content_file="$tmp_content"
  fi

  if [[ ! -s "$content_file" ]]; then
    [[ -z "$tmp_content" ]] || rm -f "$tmp_content"
    die "append content must not be empty"
  fi

  path="$APPEND_TEXT_PATH"
  payload="$("$JQ_BIN" -Rs \
    --arg path "$path" \
    --argjson newline_before "$APPEND_TEXT_NEWLINE_BEFORE" \
    '{path:$path, content: ., newline_before:$newline_before}' < "$content_file")"
  if ! response="$(http_json POST "/api/v1/mailboxes/${MAILBOX_ID}/files/append_text" "$payload")"; then
    [[ -z "$tmp_content" ]] || rm -f "$tmp_content"
    return 1
  fi
  [[ -z "$tmp_content" ]] || rm -f "$tmp_content"
  printf "%s\n" "$response"
}

archive_mailbox() {
  [[ -n "$MAILBOX_ID" ]] || die "archive requires --mailbox-id"
  http_json POST "/api/v1/mailboxes/${MAILBOX_ID}/archive" "{}"
}

unarchive_mailbox() {
  [[ -n "$MAILBOX_ID" ]] || die "unarchive requires --mailbox-id"
  http_json POST "/api/v1/mailboxes/${MAILBOX_ID}/unarchive" "{}"
}

delete_mailbox() {
  local mailbox_response account_response state token directory path claimed now expires payload response
  directory="$REVDOKU_CONFIG_DIR/delete-confirmations"
  [[ ! -L "$directory" ]] || die "refusing symlink confirmation storage"
  if [[ -d "$directory" ]]; then
    directory="$(cd -P -- "$directory" && pwd -P)"
  fi
  now="$(date +%s)"
  if [[ -n "$DELETE_CONFIRMATION" ]]; then
    [[ "$DELETE_CONFIRMATION" =~ ^[a-f0-9]{64}$ ]] || die "invalid deletion preview token"
    path="$directory/$DELETE_CONFIRMATION.json"
    [[ -f "$path" && ! -L "$path" ]] || die "deletion preview is missing or already consumed"
    "$JQ_BIN" -e --argjson now "$now" --arg origin "$BASE_URL" --arg account "$ACCOUNT_ID" --arg mailbox "$MAILBOX_ID" \
      '.expires_at > $now and .state.origin == $origin and .state.account.id == $account and .state.mailbox.id == $mailbox' "$path" >/dev/null || die "deletion preview expired or targets differ; preview again"
  fi
  mailbox_response="$(http_json GET "/api/v1/mailboxes/${MAILBOX_ID}" "{}")" || return 1
  account_response="$(http_json GET "/api/v1/accounts/${ACCOUNT_ID}" "{}")" || return 1
  # The preview binds the confirmation to the file-tree version, the settings
  # version and the counts. Any change between preview and confirm stops it.
  state="$(printf '%s\n%s\n' "$mailbox_response" "$account_response" | "$JQ_BIN" -csS --arg origin "$BASE_URL" '
    .[0].data.mailbox as $b | .[1].data.account as $account |
    if (($b.metadata_version | type == "string" and length > 0) and
        ($b | has("version_id")) and ($b.version_id | . == null or type == "string") and
        ($b.version_number | type == "number") and ($b.files_count | type == "number")) | not
    then error("Incomplete mailbox deletion state; update the client or review in the dashboard") else
    {origin:$origin, account:($account | {id,name}),
     mailbox:($b | {id, email:{address:.email.address}, account_id, archived, archived_at, metadata_version,
       version_id, version_number, files_count, storage_bytes, delete, dashboard_url})}
    end')" || return 1
  "$JQ_BIN" -e --arg account "$ACCOUNT_ID" --arg mailbox "$MAILBOX_ID" '
    .account.id == $account and .mailbox.id == $mailbox and
    (.mailbox.account_id == null or .mailbox.account_id == $account) and
    .mailbox.archived == true and .mailbox.delete.allowed == true and (.mailbox.delete.confirmation | type == "string" and length > 0)' <<<"$state" >/dev/null || die "mailbox is not eligible for deletion in the selected account; review its action guidance in the dashboard"

  if [[ -z "$DELETE_CONFIRMATION" ]]; then
    mkdir -p -- "$directory"
    [[ ! -L "$directory" ]] || die "refusing symlink confirmation storage"
    directory="$(cd -P -- "$directory" && pwd -P)"
    chmod 0700 "$directory"
    token="$(openssl rand -hex 32)"
    expires=$((now + 600))
    "$JQ_BIN" -cn --argjson state "$state" --argjson expires "$expires" \
      '{state:$state,expires_at:$expires}' | atomic_private_write "$directory/$token.json"
    "$JQ_BIN" -cn --argjson state "$state" --arg token "$token" --argjson expires "$expires" \
      '$state | del(.mailbox.delete.confirmation) | {success:true, data:(. + {
        preview:true, irreversible:true, confirmation_token:$token, expires_at:$expires,
        dashboard_url:.mailbox.dashboard_url,
        notice:"Permanently deletes this mailbox, its emails, files and versions. Obtain user approval for this exact target before --confirm-delete."})}'
    return 0
  fi

  "$JQ_BIN" -e --argjson state "$state" --argjson now "$(date +%s)" '.state == $state and .expires_at > $now' "$path" >/dev/null || die "mailbox deletion state changed; preview again"
  claimed="$(mktemp "$directory/.consumed.XXXXXX")"
  if ! mv "$path" "$claimed" 2>/dev/null; then
    rm -f "$claimed"
    die "deletion preview was already consumed"
  fi
  rm -f "$claimed"
  payload="$("$JQ_BIN" -c '{confirmation:.mailbox.delete.confirmation}' <<<"$state")"
  if ! response="$(http_json DELETE "/api/v1/mailboxes/${MAILBOX_ID}" "$payload")"; then
    echo "Deletion was not confirmed. Check mailbox status before creating another preview; this token is consumed." >&2
    return 1
  fi
  printf '%s\n' "$response"
}

connection_status() {
  http_json GET "/api/v1/status" "{}" | "$JQ_BIN" -c '{
    success: (.success // true),
    data: {
      connected: (.data.connected // true),
      account: .data.account,
      user: .data.user,
      default_account_id: .data.default_account_id,
      accounts: .data.accounts,
      connection: .data.connection,
      features: .data.features,
      dashboard_url: .data.dashboard_url
    }
  }'
}

create_client_account() {
  local payload
  payload="$("$JQ_BIN" -cn --arg name "$CLIENT_ACCOUNT_NAME" --arg client_name "$CLIENT_DISPLAY_NAME" '{name: $name} + (if $client_name == "" then {} else {client_name: $client_name} end)')"
  http_json POST "/api/v1/accounts" "$payload"
}

account_status() {
  local identity limits
  identity="$(http_json GET "/api/v1/status" "{}")" || return 1
  limits="$(http_json GET "/api/v1/account/limits" "{}")" || return 1
  "$JQ_BIN" -nc --argjson identity "$identity" --argjson limits "$limits" '{
    success: true,
    data: {
      account: $identity.data.account,
      default_account_id: $identity.data.default_account_id,
      accounts: $identity.data.accounts,
      limits: $limits.data.limits,
      usage: $limits.data.usage
    }
  }'
}

print_terminal_link_hint() {
  if [[ -t 2 ]]; then
    echo "Tip: Cmd-click the link on macOS, or Ctrl-click it on Windows/Linux, if your terminal supports clickable links." >&2
  fi
}

browser_login_link() {
  local payload response url redirect_path
  payload="$("$JQ_BIN" -nc --arg redirect_path "$BROWSER_LOGIN_PATH" '{redirect_path:$redirect_path}')"
  response="$(http_json POST "/api/v1/agent_auth/browser_login_link" "$payload")"
  url="$("$JQ_BIN" -r '.data.url // empty' <<<"$response")"
  redirect_path="$("$JQ_BIN" -r '.data.redirect_path // empty' <<<"$response")"
  [[ -n "$url" ]] || die "browser login response did not include url"
  validate_api_url "$url"
  echo "Open Revdoku: $url" >&2
  [[ -n "$redirect_path" ]] && echo "Destination: $redirect_path" >&2
  echo "Sign in normally if your browser does not already have a Revdoku session." >&2
  print_terminal_link_hint
  printf "%s\n" "$url"
}

# Best-effort, throttled (~24h), never-blocking notice when the server advertises
# a newer client/connector version than the one install.sh stamped. Compares the
# server's /api/v1/status client_version against ~/.revdoku/client_version and
# only nudges when the server version is strictly newer (numeric compare via jq;
# avoids relying on `sort -V`, which is unavailable on busybox/older BSD sort).
maybe_notify_update() {
  [[ -n "$API_KEY" ]] || return 0
  command -v "$JQ_BIN" >/dev/null 2>&1 || return 0

  local now last installed latest body
  now="$(date +%s 2>/dev/null || echo 0)"
  if [[ -f "$UPDATE_CHECK_STAMP" ]]; then
    last="$(cat "$UPDATE_CHECK_STAMP" 2>/dev/null || echo 0)"
    if [[ "$now" -gt 0 && "$last" =~ ^[0-9]+$ && $((now - last)) -lt 86400 ]]; then
      return 0
    fi
  fi
  mkdir -p "$REVDOKU_CONFIG_DIR" 2>/dev/null || true
  printf '%s' "$now" | atomic_private_write "$UPDATE_CHECK_STAMP" 2>/dev/null || true

  installed="$(installed_client_version)"
  [[ "$installed" != "unknown" ]] || return 0
  body="$(safe_curl -fsS --max-time 5 --url "$(api_url "/api/v1/status")" -H "Authorization: Bearer $API_KEY" -H "Accept: application/json" 2>/dev/null || true)"
  [[ -n "$body" ]] || return 0
  latest="$("$JQ_BIN" -r '.data.client_version // empty' <<<"$body" 2>/dev/null || true)"
  [[ -n "$latest" && "$latest" != "$installed" ]] || return 0
  if "$JQ_BIN" -ne --arg inst "$installed" --arg lat "$latest" \
    '($inst | split(".") | map(tonumber? // 0)) < ($lat | split(".") | map(tonumber? // 0))' >/dev/null 2>&1; then
    echo "Revdoku CLI update available (${installed} → ${latest}). Update using your original installation method: https://revdoku.com/llms-install.md" >&2
  fi
}

[[ "$DRY_RUN" == "true" || "$ACTION" == "delete_mailbox" ]] || maybe_notify_update || true

case "$ACTION" in
  webhook|webhook-set|webhook-delete|email-subscription)
    [[ "$MAILBOX_ID" =~ ^bkt_[A-Za-z0-9]+$ ]] || die "Provide --mailbox-id ID"
    case "$ACTION" in
      webhook) http_json GET "/api/v1/mailboxes/$MAILBOX_ID/email/webhook" "{}" ;;
      webhook-set)
        [[ -n "$WEBHOOK_URL" ]] || die "Provide --webhook-url HTTPS_URL"
        http_json PUT "/api/v1/mailboxes/$MAILBOX_ID/email/webhook" "$("$JQ_BIN" -n --arg url "$WEBHOOK_URL" --argjson rotate "$ROTATE_SECRET" '{webhook_url:$url,rotate_secret:$rotate}')" ;;
      webhook-delete)
        [[ "$DELETE_CONFIRMATION" == "$MAILBOX_ID" ]] || die "Repeat with --confirm-delete $MAILBOX_ID to disable this webhook"
        http_json DELETE "/api/v1/mailboxes/$MAILBOX_ID/email/webhook" "{}" ;;
      email-subscription) http_json GET "/api/v1/mailboxes/$MAILBOX_ID/email/subscription" "{}" ;;
    esac
    exit 0 ;;
  account_limits)
    http_json GET "/api/v1/account/limits" "{}"
    exit 0
    ;;
  get_account)
    http_json GET "/api/v1/accounts/${ACCOUNT_DETAILS_ID}" "{}"
    exit 0
    ;;
  list_accounts)
    http_json GET "/api/v1/accounts" "{}"
    exit 0
    ;;
  list_emails|email|email-status|email-download|email-delete|email-send)
    email_command
    exit 0
    ;;
  create_mailbox)
    create_mailbox
    exit 0
    ;;
  list_mailboxes)
    list_mailboxes
    exit 0
    ;;
  mailbox_status)
    [[ -n "$MAILBOX_ID" ]] || die "mailbox requires --mailbox-id or a bound folder"
    http_json GET "/api/v1/mailboxes/${MAILBOX_ID}/email" "{}"
    exit 0
    ;;
  list_files)
    list_files
    exit 0
    ;;
  read_file)
    read_file
    exit 0
    ;;
  list_versions)
    list_versions
    exit 0
    ;;
  restore_version)
    restore_version
    exit 0
    ;;
  append_text_file)
    append_text_file
    exit 0
    ;;
  archive_mailbox)
    archive_mailbox
    exit 0
    ;;
  unarchive_mailbox)
    unarchive_mailbox
    exit 0
    ;;
  delete_mailbox)
    delete_mailbox
    exit 0
    ;;
  create_client_account)
    create_client_account
    exit 0
    ;;
  account_status)
    account_status
    exit 0
    ;;
  connection_status)
    connection_status
    if [[ "$SHOW_UPLOAD_HINT" == "true" ]]; then
      echo "Tip: run 'revdoku upload .' to save this folder, or 'revdoku --help' for all commands." >&2
    fi
    exit 0
    ;;
  open_dashboard)
    open_dashboard
    exit 0
    ;;
esac

[[ -e "$PATH_TO_STORE" ]] || die "$PATH_TO_STORE does not exist"
[[ ! -L "$PATH_TO_STORE" ]] || die "symlink upload paths are not supported"

abs_path() {
  local path="$1"
  if [[ -d "$path" ]]; then
    (cd "$path" && pwd -P)
  else
    local dir base
    dir="$(dirname "$path")"
    base="$(basename "$path")"
    printf "%s/%s" "$(cd "$dir" && pwd -P)" "$base"
  fi
}

ROOT_PATH="$(abs_path "$PATH_TO_STORE")"
if [[ -d "$ROOT_PATH" ]]; then
  REVDOKU_PROJECT_FILE="$ROOT_PATH/.revdoku"
fi

effective_metadata_json() {
  printf "%s" "$METADATA_JSON"
}

content_type_for() {
  local file="$1"
  local lower="${file##*.}"
  lower="$(printf "%s" "$lower" | tr '[:upper:]' '[:lower:]')"
  case "$lower" in
    html|htm) echo "text/html" ;;
    css|csss|scss|sass|less|styl|stylus) echo "text/css" ;;
    js|mjs|cjs) echo "text/javascript" ;;
    map) echo "application/json" ;;
    webmanifest) echo "application/manifest+json" ;;
    json) echo "application/json" ;;
    txt) echo "text/plain" ;;
    md) echo "text/markdown" ;;
    png) echo "image/png" ;;
    apng) echo "image/apng" ;;
    jpg|jpe|jpeg|jfif|pjp|pjpeg) echo "image/jpeg" ;;
    webp) echo "image/webp" ;;
    gif) echo "image/gif" ;;
    avif) echo "image/avif" ;;
    bmp) echo "image/bmp" ;;
    ico|cur) echo "image/x-icon" ;;
    heic|heics) echo "image/heic" ;;
    heif|heifs) echo "image/heif" ;;
    jp2) echo "image/jp2" ;;
    svg) echo "image/svg+xml" ;;
    woff) echo "font/woff" ;;
    woff2) echo "font/woff2" ;;
    ttf) echo "font/ttf" ;;
    otf) echo "font/otf" ;;
    wasm) echo "application/wasm" ;;
    pdf) echo "application/pdf" ;;
    xml) echo "application/xml" ;;
    rss) echo "application/rss+xml" ;;
    atom) echo "application/atom+xml" ;;
    mp4) echo "video/mp4" ;;
    mov) echo "video/quicktime" ;;
    webm) echo "video/webm" ;;
    m4v) echo "video/x-m4v" ;;
    ogv) echo "video/ogg" ;;
    avi) echo "video/x-msvideo" ;;
    mkv) echo "video/x-matroska" ;;
    mpg|mpeg) echo "video/mpeg" ;;
    ts) echo "video/mp2t" ;;
    m3u8) echo "application/vnd.apple.mpegurl" ;;
    mp3) echo "audio/mpeg" ;;
    ogg|oga) echo "audio/ogg" ;;
    wav) echo "audio/wav" ;;
    m4a) echo "audio/mp4" ;;
    aac) echo "audio/aac" ;;
    flac) echo "audio/flac" ;;
    opus) echo "audio/opus" ;;
    *) echo "application/octet-stream" ;;
  esac
}

file_size() {
  wc -c < "$1" | tr -d '[:space:]'
}

md5_base64() {
  openssl dgst -md5 -binary "$1" | base64 | tr -d '\r\n'
}

sha256_file() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$1" | awk '{print $1}'
  elif command -v shasum >/dev/null 2>&1; then
    shasum -a 256 "$1" | awk '{print $1}'
  else
    openssl dgst -sha256 "$1" | awk '{print $2}'
  fi
}

# The server stores paths in Unicode NFC. macOS can return decomposed (NFD)
# names, so compose them before they become upload paths.
nfc_text() {
  local LC_ALL=C
  case "$1" in
    *[!\ -~]*) ;;
    *) printf '%s' "$1"; return ;;
  esac
  perl -MUnicode::Normalize -CSA -e 'print NFC($ARGV[0])' -- "$1" 2>/dev/null || printf '%s' "$1"
}

relative_path_for() {
  local file="$1"
  if [[ -f "$ROOT_PATH" ]]; then
    nfc_text "$(basename "$file")"
  else
    nfc_text "$(printf "%s/%s" "$(basename "$ROOT_PATH")" "${file#"$ROOT_PATH"/}")"
  fi
}

file_identity() {
  local value
  if value="$(stat -c '%d:%i' "$1" 2>/dev/null)"; then
    printf '%s' "$value"
  else
    stat -f '%d:%i' "$1"
  fi
}

local_file_for_relative_path() {
  local rel="$1" entry file
  [[ -n "$rel" && "$rel" != /* && "$rel" != *'\'* ]] || return 1
  case "/$rel/" in *'/../'*|*'/./'*|*'//'*) return 1 ;; esac
  entry="$("$JQ_BIN" -ce --arg rel "$rel" '[.[] | select(.path == $rel)] | if length == 1 then .[0] else error("unknown upload path") end' "$UPLOAD_LOCAL_MAP")" || return 1
  file="$("$JQ_BIN" -r '.local_path' <<<"$entry")"
  [[ -f "$file" ]] && no_symlink_components "$file" || return 1
  [[ "$(file_identity "$file")" == "$("$JQ_BIN" -r '.identity' <<<"$entry")" ]] || return 1
  [[ "$(file_size "$file")" == "$("$JQ_BIN" -r '.byte_size' <<<"$entry")" ]] || return 1
  [[ "$(sha256_file "$file")" == "$("$JQ_BIN" -r '.sha256' <<<"$entry")" ]] || return 1
  printf '%s' "$file"
}

validate_upload_descriptors() {
  local response="$1" requested="$2"
  "$JQ_BIN" -e --argjson requested "$requested" '
    .data.uploads as $uploads |
    ($uploads | type == "array") and
    ([$uploads[].path] | length == (unique | length)) and
    all($uploads[]; .path as $p | ($p | type == "string") and
      ([$requested[] | select(.path == $p)] | length == 1))' <<<"$response" >/dev/null || {
      echo "error: upload response contains unknown or duplicate paths" >&2
      return 1
    }
}

create_mailbox_id() {
  local payload response id
  payload="$(mailbox_payload)"
  response="$(http_json POST "/api/v1/mailboxes" "$payload")" ||
    die "mailbox create failed; to store files in an existing mailbox, pass --mailbox-id ID (see 'revdoku ls')"
  id="$("$JQ_BIN" -r '.data.mailbox.id // empty' <<<"$response")"
  validate_id mailbox_id "$id"
  printf "%s" "$id"
}

mailbox_payload() {
  "$JQ_BIN" -nc \
    --arg description "$DESCRIPTION" \
    --argjson metadata "$(effective_metadata_json)" \
    '{mailbox: ({metadata: $metadata} + (if $description != "" then {description: $description} else {} end))}'
}

mailbox_update_payload() {
  "$JQ_BIN" -nc \
    --arg description "$DESCRIPTION" \
    --argjson metadata "$METADATA_JSON" \
    '{mailbox: ((if $description != "" then {description: $description} else {} end)
      + (if ($metadata | length) > 0 then {metadata: $metadata} else {} end))}'
}

mailbox_update_needed() {
  [[ "$METADATA_JSON" != "{}" || -n "$DESCRIPTION" ]]
}

put_direct_upload() {
  local upload_json="$1"
  local file="$2"
  local url header_args=() body_file status curl_status attempt delay
  LAST_DIRECT_UPLOAD_STATUS=""
  url="$("$JQ_BIN" -r '.url // empty' <<<"$upload_json")"
  validate_transfer_url "$url" || { echo "error: upload destination is not approved" >&2; return 1; }
  "$JQ_BIN" -e '(.headers // {}) | type == "object" and all(to_entries[];
    (.key | test("^[A-Za-z0-9-]+$")) and
    (.key | ascii_downcase | test("^(content-type|content-md5|content-length|content-disposition|x-amz-[a-z0-9-]+)$")) and
    (.value | type == "string" and (test("[\\x00-\\x1f\\x7f]") | not)))' <<<"$upload_json" >/dev/null || {
      echo "error: unsafe storage upload headers" >&2
      return 1
    }
  while IFS= read -r header; do
    header_args+=(-H "$header")
  done < <("$JQ_BIN" -r '.headers // {} | to_entries[] | .key + ": " + .value' <<<"$upload_json")

  attempt=0
  while true; do
    [[ "$(local_file_for_relative_path "$(relative_path_for "$file")")" == "$file" ]] || { echo "error: selected upload file changed" >&2; return 1; }
    body_file="$(mktemp)"
    # Bash 3 with nounset treats an empty array as unset.
    if status="$(safe_curl -sS -o "$body_file" -w "%{http_code}" -X PUT ${header_args[@]+"${header_args[@]}"} --data-binary "@${file}" --url "$url")"; then
      curl_status=0
    else
      curl_status=$?
    fi

    if [[ "$curl_status" == "0" ]] && http_status_success "$status"; then
      LAST_DIRECT_UPLOAD_STATUS="$status"
      rm -f "$body_file"
      return 0
    fi

    if (( attempt < DIRECT_UPLOAD_MAX_ATTEMPTS )) && { [[ "$curl_status" != "0" ]] || http_status_retryable "$status"; }; then
      attempt=$((attempt + 1))
      delay="$(retry_delay_for_attempt "$attempt")"
      if [[ "$curl_status" != "0" ]]; then
        echo "Direct upload network error; retrying in ${delay}s (${attempt}/${DIRECT_UPLOAD_MAX_ATTEMPTS})..." >&2
      else
        echo "Direct upload HTTP $status; retrying in ${delay}s (${attempt}/${DIRECT_UPLOAD_MAX_ATTEMPTS})..." >&2
      fi
      rm -f "$body_file"
      sleep "$delay"
      continue
    fi

    if [[ "$curl_status" != "0" ]]; then
      LAST_DIRECT_UPLOAD_STATUS=""
      echo "error: direct upload failed (curl exit $curl_status)" >&2
    else
      LAST_DIRECT_UPLOAD_STATUS="$status"
      echo "error: direct upload failed (HTTP $status)" >&2
      if [[ -s "$body_file" ]]; then
        cat "$body_file" >&2
      fi
    fi
    rm -f "$body_file"
    return 1
  done
}

upload_file_direct() {
  local mailbox_id="$1"
  local file="$2"
  local file_list
  file_list="$(mktemp)"
  printf "%s\0" "$file" > "$file_list"
  store_mailbox_session_upload "$mailbox_id" "$file_list"
  local status=$?
  rm -f "$file_list"
  return "$status"
}

upload_file() {
  local mailbox_id="$1"
  local file="$2"
  local rel
  rel="$(relative_path_for "$file")"
  echo "Uploading $rel" >&2

  upload_file_direct "$mailbox_id" "$file"
}

mailbox_upload_session_manifest_json() {
  local file_list="$1"
  local manifest_lines converted_map rel filename content_type size checksum sha256 identity
  manifest_lines="$(mktemp "$upload_session_tmp/manifest.XXXXXX")" || return 1
  converted_map="$(mktemp "$upload_session_tmp/map.XXXXXX")" || return 1
  : > "$UPLOAD_LOCAL_MAP"
  while IFS= read -r -d '' file; do
    no_symlink_components "$file" || return 1
    identity="$(file_identity "$file")"
    rel="$(relative_path_for "$file")"
    filename="$(basename "$file")"
    content_type="$(content_type_for "$file")"
    size="$(file_size "$file")"
    checksum="$(md5_base64 "$file")"
    sha256="$(sha256_file "$file")"
    "$JQ_BIN" -nc --arg path "$rel" --arg local_path "$file" --arg identity "$identity" --arg sha256 "$sha256" --argjson byte_size "$size" \
      '{path:$path,local_path:$local_path,identity:$identity,sha256:$sha256,byte_size:$byte_size}' >> "$UPLOAD_LOCAL_MAP"
    "$JQ_BIN" -nc \
      --arg path "$rel" \
      --argjson byte_size "$size" \
      --arg content_type "$content_type" \
      --arg checksum "$checksum" \
      --arg sha256 "$sha256" \
      '{path:$path, byte_size:$byte_size, content_type:$content_type, checksum:$checksum, sha256:$sha256}' >> "$manifest_lines"
  done < "$file_list"
  "$JQ_BIN" -sc '.' "$UPLOAD_LOCAL_MAP" > "$converted_map" || return 1
  mv "$converted_map" "$UPLOAD_LOCAL_MAP" || return 1
  "$JQ_BIN" -sc '.' "$manifest_lines"
  rm -f "$manifest_lines"
}

mailbox_upload_session_client_key() {
  local mailbox_id="$1"
  local manifest_json="$2"
  local digest
  if [[ -n "$MAILBOX_UPLOAD_CLIENT_SESSION_KEY" ]]; then
    printf "%s" "$MAILBOX_UPLOAD_CLIENT_SESSION_KEY"
    return 0
  fi
  digest="$(printf "%s:%s:%s" "$mailbox_id" "$manifest_json" "$ACTION_REASON" | openssl dgst -sha256 -hex | awk '{print $2}')"
  printf "cli:%s:%s" "$mailbox_id" "$digest"
}

mailbox_upload_session_payload() {
  local client_session_key="$1"
  local expected_file_count="$2"
  "$JQ_BIN" -nc \
    --arg client_session_key "$client_session_key" \
    --argjson expected_file_count "$expected_file_count" \
    '{client_session_key: $client_session_key, expected_file_count: $expected_file_count}'
}

prepare_mailbox_upload_descriptors() {
  local mailbox_id="$1"
  local session_id="$2"
  local batch_json="$3"
  local payload
  payload="$("$JQ_BIN" -nc --argjson files "$batch_json" '{files: $files}')"
  http_json POST "/api/v1/mailboxes/${mailbox_id}/upload_sessions/${session_id}/uploads" "$payload"
}

finalize_mailbox_upload_session() {
  local mailbox_id="$1"
  local session_id="$2"
  local complete="${3:-true}"
  local payload response pending attempts=0 remaining
  local max_attempts="${REVDOKU_FINALIZE_MAX_ATTEMPTS:-1000}"
  [[ -n "$session_id" ]] || return 0
  "$JQ_BIN" -nc --argjson complete "$complete" '{complete:$complete}' | {
    payload="$(cat)"
    while :; do
      response="$(http_json POST "/api/v1/mailboxes/${mailbox_id}/upload_sessions/${session_id}/finalize" "$payload")" || return 1
      pending="$("$JQ_BIN" -r '.data.finalize_pending // false' <<<"$response")"
      [[ "$pending" == "true" && "$complete" == "true" ]] || return 0
      attempts=$((attempts + 1))
      remaining="$("$JQ_BIN" -r '.data.remaining_files_count // .data.mailbox_upload_session.remaining_files_count // empty' <<<"$response" 2>/dev/null || true)"
      if (( attempts == 1 || attempts % 5 == 0 )); then
        if [[ -n "$remaining" && "$remaining" != "null" ]]; then
          echo "Still finalizing ${remaining} file(s)… (attempt ${attempts})" >&2
        else
          echo "Still finalizing files… (attempt ${attempts})" >&2
        fi
      fi
      if (( attempts >= max_attempts )); then
        echo "Timed out finalizing the upload session after ${attempts} attempts (~$((attempts * 2 / 60)) min)." >&2
        echo "Files may still be processing in the background; re-run the command to resume." >&2
        return 1
      fi
      sleep 2
    done
  }
}

finalize_mailbox_upload_session_batch() {
  local mailbox_id="$1"
  local session_id="$2"
  local limit="${3:-100}"
  local attempts=0 missing_entry_json missing_path
  [[ -n "$session_id" ]] || return 0
  "$JQ_BIN" -nc --argjson limit "$limit" '{limit:$limit}' | {
    local payload
    payload="$(cat)"
    while :; do
      if http_json POST "/api/v1/mailboxes/${mailbox_id}/upload_sessions/${session_id}/finalize_batch" "$payload" >/dev/null; then
        return 0
      fi

      if [[ "${LAST_ERROR_CODE:-}" == "DIRECT_UPLOAD_NOT_FOUND" && "$attempts" -lt "$MAILBOX_UPLOAD_DESCRIPTOR_BATCH_SIZE" ]]; then
        missing_entry_json="$LAST_ERROR_DETAILS_JSON"
        missing_path="$("$JQ_BIN" -r '.path // empty' <<<"$missing_entry_json" 2>/dev/null || true)"
        if [[ -n "$missing_path" ]] && upload_mailbox_session_missing_entry "$mailbox_id" "$session_id" "$missing_entry_json"; then
          attempts=$((attempts + 1))
          echo "Retrying mailbox upload batch finalize after refreshing $missing_path." >&2
          continue
        fi
      fi

      return 1
    done
  }
}

upload_mailbox_session_missing_entry() {
  local mailbox_id="$1"
  local session_id="$2"
  local entry_json="$3"
  local rel file response upload_json

  rel="$("$JQ_BIN" -r '.path // empty' <<<"$entry_json" 2>/dev/null || true)"
  [[ -n "$rel" ]] || return 1
  file="$(local_file_for_relative_path "$rel")" || {
    echo "error: upload session asked to refresh unknown upload path: $rel" >&2
    return 1
  }

  echo "Refreshing missing direct upload for $rel." >&2
  entry_json="$("$JQ_BIN" -ce --arg rel "$rel" 'map(select(.path == $rel))[0] // error("unknown retry path")' <<<"$UPLOAD_MANIFEST")" || return 1
  response="$(prepare_mailbox_upload_descriptors "$mailbox_id" "$session_id" "[$entry_json]")" || return 1
  validate_upload_descriptors "$response" "[$entry_json]" || return 1
  upload_json="$("$JQ_BIN" -c '.data.uploads[0].upload // empty' <<<"$response")"
  [[ -n "$upload_json" && "$upload_json" != "null" ]] || return 1

  echo "Uploading $rel" >&2
  put_direct_upload "$upload_json" "$file"
}

store_mailbox_session_upload() (
  local mailbox_id="$1"
  local file_list="$2"
  local manifest_json payload response session_id upload_line rel upload_json file batch_json batch_response expected_file_count client_session_key failed=0 finalized=0 entry_json refresh_response uploaded_index=0
  local upload_session_tmp
  upload_session_tmp="$(mktemp -d "${TMPDIR:-/tmp}/revdoku-upload.XXXXXX")" || return 1
  trap 'rm -rf "$upload_session_tmp"' EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM
  trap 'exit 129' HUP
  UPLOAD_LOCAL_MAP="$upload_session_tmp/local-map.json"
  manifest_json="$(mailbox_upload_session_manifest_json "$file_list")" || { rm -f "$UPLOAD_LOCAL_MAP"; return 1; }
  UPLOAD_MANIFEST="$manifest_json"
  expected_file_count="$("$JQ_BIN" -r 'length' <<<"$manifest_json")"
  client_session_key="$(mailbox_upload_session_client_key "$mailbox_id" "$manifest_json")"
  payload="$(mailbox_upload_session_payload "$client_session_key" "$expected_file_count")"
  response="$(http_json POST "/api/v1/mailboxes/${mailbox_id}/upload_sessions" "$payload")" || return 1
  session_id="$("$JQ_BIN" -r '.data.mailbox_upload_session.id // empty' <<<"$response")"
  validate_id upload_session_id "$session_id"
  echo "Mailbox upload session: $session_id" >&2

  while IFS= read -r batch_json; do
    [[ -n "$batch_json" && "$batch_json" != "[]" ]] || continue
    batch_response="$(prepare_mailbox_upload_descriptors "$mailbox_id" "$session_id" "$batch_json")" || {
      failed=1
      break
    }
    validate_upload_descriptors "$batch_response" "$batch_json" || { failed=1; break; }
    while IFS= read -r upload_line; do
      [[ -n "$upload_line" ]] || continue
      rel="$("$JQ_BIN" -r '.path' <<<"$upload_line")"
      upload_json="$("$JQ_BIN" -c '.upload' <<<"$upload_line")"
      file="$(local_file_for_relative_path "$rel")" || {
        echo "error: upload session asked for unknown upload path: $rel" >&2
        failed=1
        break
      }
      uploaded_index=$((uploaded_index + 1))
      echo "Uploading ${uploaded_index}/${expected_file_count}: $rel" >&2
      if ! put_direct_upload "$upload_json" "$file"; then
        if [[ "${LAST_DIRECT_UPLOAD_STATUS:-}" == "403" || "${LAST_DIRECT_UPLOAD_STATUS:-}" == "404" ]]; then
          entry_json="$("$JQ_BIN" -c --arg rel "$rel" 'map(select(.path == $rel))[0] // empty' <<<"$batch_json")"
          if [[ -n "$entry_json" ]] && refresh_response="$(prepare_mailbox_upload_descriptors "$mailbox_id" "$session_id" "[$entry_json]")"; then
            validate_upload_descriptors "$refresh_response" "[$entry_json]" || { failed=1; break; }
            upload_json="$("$JQ_BIN" -c '.data.uploads[0].upload // empty' <<<"$refresh_response")"
            if [[ -n "$upload_json" ]] && put_direct_upload "$upload_json" "$file"; then
              continue
            fi
          fi
        fi
        echo "error: upload failed for $rel" >&2
        failed=1
        break
      fi
    done < <("$JQ_BIN" -c '.data.uploads[]?' <<<"$batch_response")
    [[ "$failed" == "0" ]] || break

    if ! finalize_mailbox_upload_session_batch "$mailbox_id" "$session_id" "$MAILBOX_UPLOAD_DESCRIPTOR_BATCH_SIZE"; then
      failed=1
      break
    fi
  done < <("$JQ_BIN" -c --argjson size "$MAILBOX_UPLOAD_DESCRIPTOR_BATCH_SIZE" 'range(0; length; $size) as $i | .[$i:($i + $size)]' <<<"$manifest_json")

  if [[ "$failed" == "0" ]] && finalize_mailbox_upload_session "$mailbox_id" "$session_id" true; then
    finalized=1
  else
    failed=1
  fi
  if [[ "$finalized" != "1" ]]; then
    finalize_mailbox_upload_session "$mailbox_id" "$session_id" false >/dev/null 2>&1 || true
  fi
  rm -f "$UPLOAD_LOCAL_MAP"
  return "$failed"
)

mailbox_id_for_storage() {
  if [[ -n "$MAILBOX_ID" ]]; then
    if mailbox_update_needed; then
      local payload
      payload="$(mailbox_update_payload)"
      http_json PATCH "/api/v1/mailboxes/${MAILBOX_ID}" "$payload" >/dev/null
    fi
    printf "%s" "$MAILBOX_ID"
  else
    create_mailbox_id
  fi
}

store_mailbox() {
  local mailbox_id mailbox_id_file file_list
  file_list="$(mktemp)"
  if ! collect_files > "$file_list"; then
    rm -f "$file_list"
    return 1
  fi
  if [[ ! -s "$file_list" ]]; then
    rm -f "$file_list"
    die "no files found to store after safety exclusions"
  fi

  mailbox_id_file="$(mktemp)"
  if ! mailbox_id_for_storage > "$mailbox_id_file"; then
    rm -f "$mailbox_id_file" "$file_list"
    return 1
  fi
  mailbox_id="$(cat "$mailbox_id_file")"
  rm -f "$mailbox_id_file"
  [[ -n "$mailbox_id" ]] || {
    rm -f "$file_list"
    die "mailbox id is required before uploading files"
  }
  echo "Mailbox: $mailbox_id" >&2
  echo "Saved mailbox: $mailbox_id" >&2
  store_mailbox_session_upload "$mailbox_id" "$file_list" || {
    rm -f "$file_list"
    return 1
  }
  rm -f "$file_list"
  printf "%s" "$mailbox_id"
}

collect_files() {
  if [[ -f "$ROOT_PATH" ]]; then
    if should_skip_storage_path "$ROOT_PATH"; then
      die "refusing to store file from Revdoku upload safety list: $(basename "$ROOT_PATH")"
    fi
    printf "%s\0" "$ROOT_PATH"
    return
  fi

  find -P "$ROOT_PATH" \
    \( -type d \( -name ".git" -o -name ".hg" -o -name ".svn" -o -name ".revdoku" -o -name ".terraform" -o -name ".cache" -o -name ".parcel-cache" -o -name ".turbo" -o -name ".vite" -o -name ".next" -o -name ".astro" -o -name "node_modules" -o -name ".aws" -o -name ".ssh" -o -name ".gnupg" -o -name ".azure" \) -prune -print0 \) \
    -o \( -type f -o -type l \) -print0 |
    while IFS= read -r -d '' file; do
      if [[ -L "$file" ]] || should_skip_storage_path "$file"; then
        echo "Skipping file from Revdoku upload safety list: $(relative_path_for "$file")" >&2
        if [[ -n "$SKIPPED_PATHS" ]]; then
          "$JQ_BIN" -nc --arg path "$(relative_path_for "$file")" '{path:$path,reason:"upload safety exclusion or symlink"}' >> "$SKIPPED_PATHS"
        fi
        continue
      fi
      printf "%s\0" "$file"
    done
}

should_skip_storage_path() {
  local file="$1"
  local rel name lower_rel lower_name part extension state_file confirmation_directory
  # Match path names only: return success to EXCLUDE these credential stores.
  # Never open or upload their contents; this is independent of server policy.
  case "$file" in
    */.aws|*/.aws/*|*/.ssh|*/.ssh/*|*/.gnupg|*/.gnupg/*|*/.azure|*/.azure/*|*/.config/gcloud/*|*/.docker/config.json|*/.kube/config|*/.codex/auth.json|*/.claude/.credentials.json)
      return 0 ;;
  esac
  # Keep the client's private state out even when its config paths are inside
  # the selected folder. A custom credential location must not expose sibling
  # mailbox selections, version/update stamps, or deletion preview tokens.
  for state_file in "$CREDENTIALS_PATH" "$DEFAULT_MAILBOX_PATH" "$CLIENT_VERSION_FILE" "$UPDATE_CHECK_STAMP"; do
    if [[ -e "$state_file" && "$file" == "$(abs_path "$state_file")" ]]; then
      return 0
    fi
  done
  confirmation_directory="${REVDOKU_CONFIG_DIR}/delete-confirmations"
  if [[ -d "$confirmation_directory" ]]; then
    confirmation_directory="$(abs_path "$confirmation_directory")"
    if [[ "$file" == "$confirmation_directory" || "$file" == "$confirmation_directory/"* ]]; then
      return 0
    fi
  fi
  rel="$(relative_path_for "$file")"
  name="$(basename "$file")"
  lower_rel="$(printf "%s" "$rel" | tr '[:upper:]' '[:lower:]')"
  lower_name="$(printf "%s" "$name" | tr '[:upper:]' '[:lower:]')"

  # The pattern lines below are GENERATED from apps/web/config/upload_safety.json by
  # scripts/generate-cli-upload-safety.rb so the CLI's local skip-list never drifts
  # from the server policy (the server is the hard gate; this is a local-UX mirror).
  # Edit the JSON and re-run the generator — do not hand-edit between the markers.
  IFS='/' read -r -a path_parts <<< "$lower_rel"
  for part in "${path_parts[@]}"; do
    case "$part" in
      # >>> revdoku:generated local_only_basenames
      .ds_store|__macosx|.localized|.appledouble|.lsoverride|.documentrevisions-v100|.fseventsd|.spotlight-v100|.temporaryitems|.trashes|.volumeicon.icns|.appledb|.appledesktop|.apdisk|network\ trash\ folder|temporary\ items|thumbs.db|thumbs.db:encryptable|ehthumbs.db|ehthumbs_vista.db|desktop.ini|\$recycle.bin|system\ volume\ information|.directory|.trash|lost+found|.git|.hg|.svn|.revdoku|.terraform|.cache|.parcel-cache|.turbo|.vite|.next|.astro|node_modules)
      # <<< revdoku:generated local_only_basenames
        return 0
        ;;
      # >>> revdoku:generated local_only_name_globs
      ._*|.trash-*|.fuse_hidden*|.nfs*)
      # <<< revdoku:generated local_only_name_globs
        return 0
        ;;
      agents.md|claude.md)
        # Keep local agent-instruction files out of bulk uploads.
        return 0
        ;;
      # >>> revdoku:generated prohibited_basenames
      .env|.npmrc|.pypirc|.netrc|id_rsa|id_rsa.pub|id_dsa|id_dsa.pub|id_ecdsa|id_ecdsa.pub|id_ed25519|id_ed25519.pub)
      # <<< revdoku:generated prohibited_basenames
        return 0
        ;;
      # >>> revdoku:generated prohibited_name_globs
      .env.*|env.local|env.production|env.staging|env.development|env.test|*.pem|*.key|*.p12|*.pfx|*.crt|*.cer|*.der|*.kdb|*.jks|*.mobileprovision|api-token.*|api_key.*|credentials.*|credential.*|secrets.*|secret.*|*.secret|*.secrets|private-key.*|private_key.*)
      # <<< revdoku:generated prohibited_name_globs
        return 0
        ;;
    esac
  done

  extension="${lower_name##*.}"
  if [[ "$lower_name" == *.* && "$extension" != "$lower_name" ]]; then
    case ".${extension}" in
      # >>> revdoku:generated prohibited_extensions
      .exe|.com|.scr|.pif|.cpl|.dll|.sys|.drv|.msi|.msp|.app|.dmg|.pkg|.deb|.rpm|.apk|.ipa|.jar|.jnlp|.run|.bin|.lnk|.pem|.key|.p12|.pfx|.crt|.cer|.der|.kdb|.jks|.mobileprovision|.zip|.zipx|.tar|.rar|.gz|.gzip|.tgz|.bz2|.tbz|.tbz2|.xz|.txz|.7z|.z|.lz|.lzma|.lz4|.zst|.zstd|.cab|.arj|.lzh|.lha|.war|.ear|.iso|.img|.vhd|.vhdx|.vmdk)
      # <<< revdoku:generated prohibited_extensions
        return 0
        ;;
    esac
  fi

  return 1
}

if [[ "$DRY_RUN" == "true" ]]; then
  preview_files="$(mktemp)"
  SKIPPED_PATHS="$(mktemp)"
  preview_lines="$(mktemp)"
  trap 'rm -f "$preview_files" "$SKIPPED_PATHS" "$preview_lines"' EXIT
  collect_files > "$preview_files"
  while IFS= read -r -d '' file; do
    "$JQ_BIN" -nc --arg path "$(relative_path_for "$file")" --argjson bytes "$(file_size "$file")" '{path:$path,bytes:$bytes}' >> "$preview_lines"
  done < "$preview_files"
  "$JQ_BIN" -n --slurpfile files "$preview_lines" --slurpfile skipped "$SKIPPED_PATHS" \
    --arg root "$ROOT_PATH" --arg origin "$BASE_URL" --arg account "$ACCOUNT_ID" --arg mailbox "$MAILBOX_ID" \
    '{dry_run:true,root:$root,api_origin:$origin,account_id:($account|if . == "" then null else . end),
      mailbox_id:($mailbox|if . == "" then null else . end),creates_mailbox:($mailbox == ""),
      files:$files,file_count:($files|length),bytes:([$files[].bytes]|add // 0),skipped:$skipped}'
  exit 0
fi

mailbox_id_file="$(mktemp)"
if ! store_mailbox > "$mailbox_id_file"; then
  rm -f "$mailbox_id_file"
  die "mailbox store failed"
fi
mailbox_id="$(cat "$mailbox_id_file")"
rm -f "$mailbox_id_file"
echo "Saved mailbox: $mailbox_id" >&2

# stdout stays the mailbox ID for scripts; the dashboard link goes to stderr.
echo "View in Revdoku: $APP_URL/mailboxes/view?id=$mailbox_id" >&2
write_project_binding "$mailbox_id" ""
print_terminal_link_hint
printf "%s\n" "$mailbox_id"
